const e=[{id:"q1",category:"Contract Flow",question:"When does an Offer to Purchase become binding?",options:["When the buyer signs it","When it is delivered to the seller","When it is signed and delivered","When the P&S is signed"],correctIndex:2,explanation:"An Offer to Purchase becomes binding when it is both signed AND delivered to the other party."},{id:"q2",category:"2025 Law Changes",question:"Under the 2025 MA inspection rules, which of the following is NOT allowed?",options:["Requiring buyers to waive home inspections","Setting a short inspection deadline","Limiting repairs to structural issues only","Setting a minimum repair threshold amount"],correctIndex:0,explanation:"Sellers and listing agents cannot require buyers to waive home inspections as of October 2025. However, they can still negotiate deadlines, thresholds, and scope."},{id:"q3",category:"Commission",question:"What is the 2025 rule regarding buyer-agent commissions in Massachusetts?",options:["Sellers must always pay buyer-agent commission","Buyers must always pay their own agent","Commissions are explicitly treated as fully negotiable","The state sets a standard commission rate"],correctIndex:2,explanation:"As of 2025, commissions are explicitly treated as fully negotiable between all parties. There is no requirement for who pays."},{id:"q4",category:"Dual Agency",question:"What is required before an agent can act as a dual agent in MA?",options:["Verbal consent from both parties","Written informed consent from both parties","Approval from the broker only","Filing with the state board"],correctIndex:1,explanation:"Both buyer and seller must provide written informed consent before dual agency can occur. The relationship must be disclosed before confidential information is shared."},{id:"q5",category:"Broker Relationship",question:"Which is NOT a characteristic of an independent contractor agent?",options:["Controls their own schedule","Receives a W-2 tax form","Pays their own taxes","Is not entitled to employee benefits"],correctIndex:1,explanation:"Independent contractors receive a 1099 form, not a W-2. W-2 forms are for employees who have taxes withheld by their employer."},{id:"q6",category:"Contract Flow",question:"What is the typical deposit amount at the Offer to Purchase stage?",options:["10% of purchase price","5% of purchase price","$500-$1,000","3% of purchase price"],correctIndex:2,explanation:"The initial deposit with an Offer to Purchase is typically $500-$1,000. The larger deposit (3-5%) comes at the P&S stage."},{id:"q7",category:"Commission",question:"In a 70/30 commission split with a $10,000 gross commission, how much does the agent receive?",options:["$3,000","$7,000","$5,000","$10,000"],correctIndex:1,explanation:"In a 70/30 split where the agent gets 70%, they receive $7,000 (70% of $10,000). The broker retains $3,000."},{id:"q8",category:"2025 Law Changes",question:"What is a Backup Offer Addendum used for?",options:["To submit multiple offers simultaneously","To position as second in line if the first deal falls through","To replace an existing offer","To extend the closing date"],correctIndex:1,explanation:"A Backup Offer Addendum allows a buyer to position themselves as second in line if the primary accepted offer falls through."},{id:"q9",category:"Broker Relationship",question:'What happens when an agent reaches their "cap" in a capped commission structure?',options:["They must stop working for the month","They keep 100% of commissions after that point","Their split percentage decreases","They receive a bonus from the broker"],correctIndex:1,explanation:"Once an agent reaches their cap (the maximum amount paid to the broker), they typically keep 100% of subsequent commissions for that period."},{id:"q10",category:"Dual Agency",question:"In a designated dual agency, what happens?",options:["One agent represents both parties","Two agents from the same brokerage each represent one party","The broker represents both parties","No representation is provided"],correctIndex:1,explanation:"In designated dual agency, two different agents from the same brokerage each represent one party, reducing conflicts while keeping the transaction in-house."},{id:"q11",category:"Financing",question:"What is the typical earnest money deposit at the Offer to Purchase stage?",options:["$100-$500","$500-$1,000","1% of purchase price","5% of purchase price"],correctIndex:1,explanation:"The initial earnest money with an OTP is typically $500-$1,000. The larger deposit (3-5% of purchase price) comes at the P&S stage."},{id:"q12",category:"Disclosure",question:"For homes built before 1978, what disclosure is required in Massachusetts?",options:["Asbestos disclosure","Lead paint disclosure","Radon disclosure","All of the above"],correctIndex:1,explanation:"Federal law requires lead paint disclosure for all residential properties built before 1978. Buyers must also receive a lead paint pamphlet and have 10 days to conduct a lead inspection."},{id:"q13",category:"Commission",question:"In a transaction with a $600,000 sale price and 5% commission split 60/40 (agent 60%), what does the agent earn?",options:["$15,000","$18,000","$24,000","$30,000"],correctIndex:1,explanation:"Total commission: $600,000 × 5% = $30,000. Agent receives 60%: $30,000 × 0.60 = $18,000. Broker receives $12,000."},{id:"q14",category:"Contract Flow",question:"What happens to earnest money if the buyer backs out for a valid contingency reason?",options:["Seller keeps all of it","Split 50/50 between buyer and seller","Returned to the buyer","Held until closing"],correctIndex:2,explanation:"If the buyer exercises a valid contingency (inspection, financing, etc.), the earnest money is returned to the buyer in full."},{id:"q15",category:"2025 Law Changes",question:"Under 2025 rules, what must happen before an agent shows properties to a buyer?",options:["Pre-approval letter required","Buyer Representation Agreement signed","Earnest money deposited","Home inspection scheduled"],correctIndex:1,explanation:"As of 2025, agents must have a signed Buyer Representation Agreement before showing properties, clearly outlining duties and compensation."},{id:"q16",category:"Financing",question:"What is the minimum down payment for an FHA loan?",options:["0%","3.5%","5%","10%"],correctIndex:1,explanation:"FHA loans require a minimum down payment of 3.5% with a credit score of 580 or higher. VA loans can offer 0% down for qualifying veterans."},{id:"q17",category:"Title",question:"What does a title search reveal?",options:["Property value only","Ownership history, liens, and encumbrances","Future zoning changes","Neighborhood crime rates"],correctIndex:1,explanation:"A title search examines public records to verify ownership, uncover liens, judgments, easements, and any other encumbrances that could affect the property title."},{id:"q18",category:"Broker Relationship",question:"What is the main tax difference between an independent contractor and an employee agent?",options:["ICs pay less taxes","ICs receive W-2 forms","ICs receive 1099 forms and pay self-employment tax","ICs don't pay income tax"],correctIndex:2,explanation:"Independent contractors receive 1099 forms (not W-2), must pay self-employment tax (Social Security and Medicare), and are responsible for quarterly estimated tax payments."},{id:"q19",category:"Negotiation",question:'What is a "subject to" offer in real estate?',options:["An offer with no contingencies","An offer contingent on selling another property","An offer assuming existing financing","An offer below asking price"],correctIndex:2,explanation:'A "subject to" offer means the buyer will take over existing mortgage payments without formally assuming the loan. This is risky and often violates the due-on-sale clause.'},{id:"q20",category:"Closing",question:"Who typically pays for the owner's title insurance policy in Massachusetts?",options:["Always the buyer","Always the seller","Split 50/50","Negotiable between parties"],correctIndex:3,explanation:"In Massachusetts, who pays for owner's title insurance is negotiable. Traditionally the buyer pays, but it can be negotiated as part of the deal terms."},{id:"q21",category:"Commission",question:"What happens when an agent reaches their annual cap in a capped commission structure?",options:["They must stop working until next year","Their split percentage increases","They keep 100% of subsequent commissions","They receive a bonus check"],correctIndex:2,explanation:"Once an agent has paid their annual cap amount to the broker, they typically keep 100% of all subsequent commission for that year, minus transaction fees."},{id:"q22",category:"Disclosure",question:"What is a material defect that must be disclosed?",options:["Cosmetic issues only","Any condition that significantly affects property value or desirability","Only structural problems","Nothing if buyer doesn't ask"],correctIndex:1,explanation:"Material defects are conditions that significantly affect the property's value, desirability, or safety. Sellers must disclose all known material defects, even if not asked."},{id:"q23",category:"Financing",question:"What is the debt-to-income (DTI) ratio limit for most conventional loans?",options:["28%","36%","43%","50%"],correctIndex:2,explanation:"Most conventional loans allow a maximum DTI ratio of 43%, meaning total monthly debt payments cannot exceed 43% of gross monthly income. Some loans may allow up to 50% with strong credit."},{id:"q24",category:"Contract Flow",question:"What is the typical period between P&S signing and closing in Massachusetts?",options:["7-14 days","30-45 days","60-90 days","120 days"],correctIndex:1,explanation:"The typical period between P&S and closing in MA is 30-45 days, allowing time for financing approval, inspections, title work, and final preparations."},{id:"q25",category:"2025 Law Changes",question:"Can a seller ask buyers to include inspection waiver clauses in their offers?",options:["Yes, always allowed","No, banned as of October 2025","Only for cash offers","Only for commercial properties"],correctIndex:1,explanation:"As of October 2025, sellers and listing agents cannot require or request that buyers waive home inspection rights. However, inspection timing and scope remain negotiable."},{id:"q26",category:"Antitrust",question:"Which of the following is an antitrust violation?",options:["Setting your own commission rate","Refusing to work with difficult clients","Agreeing with competing brokers to charge 6% commission","Negotiating commission with a seller"],correctIndex:2,explanation:"Price-fixing (agreeing on commission rates with competitors) is illegal under the Sherman Antitrust Act. Each broker must independently set their own rates."},{id:"q27",category:"Antitrust",question:"Two brokers agree to divide the town: one takes the north side, one takes the south. This is:",options:["Legal business strategy","Market allocation (illegal)","Acceptable if in writing","Required for fair competition"],correctIndex:1,explanation:"Market allocation is illegal under antitrust law. Competitors cannot agree to divide territories or customer types to avoid competing with each other."},{id:"q28",category:"Associations",question:"To use the REALTOR® trademark, an agent must:",options:["Just have a real estate license","Be a member of NAR and follow the Code of Ethics","Complete 100 transactions","Pay an annual fee to the state"],correctIndex:1,explanation:"The REALTOR® trademark requires membership in the National Association of REALTORS® and adherence to their Code of Ethics. It's not automatic with licensing."},{id:"q29",category:"Associations",question:"What is the primary benefit of MLS membership?",options:["Lower commission rates","Guaranteed sales","Access to cooperative listing database and broker cooperation","Automatic license renewal"],correctIndex:2,explanation:"MLS provides access to a shared database of listings, enabling broker cooperation and compensation. This significantly expands market exposure for your clients' properties."},{id:"q30",category:"Ethics",question:"Under the NAR Code of Ethics, what must you disclose when representing both sides?",options:["Nothing, if both agree verbally","Only to the buyer","Dual agency in writing to both parties before confidential information is shared","Only at closing"],correctIndex:2,explanation:"The Code of Ethics requires written disclosure of dual agency to both parties before any confidential information is shared, ensuring informed consent."},{id:"q31",category:"Antitrust",question:"A broker requires clients to use their affiliated mortgage company. This is:",options:["Smart business practice","A tie-in arrangement (illegal)","Required by law","Only illegal if the rate is high"],correctIndex:1,explanation:"Requiring the use of one service (mortgage) as a condition of another service (real estate) is a tie-in arrangement, which violates antitrust law. Clients must have freedom of choice."},{id:"q32",category:"Associations",question:"Which provides the Standard Forms used in Massachusetts real estate transactions?",options:["The state licensing board","Massachusetts Association of REALTORS® (MAR)","Individual brokerages create their own","The federal government"],correctIndex:1,explanation:"MAR provides the Standard Forms library to its members, including Offer to Purchase, P&S Agreement, and other commonly used forms in MA transactions."},{id:"q33",category:"Antitrust",question:"Multiple brokers agree not to work with a discount brokerage. This is:",options:["Fair competition","Group boycott (illegal)","Quality control","Industry standard"],correctIndex:1,explanation:"A group boycott occurs when competitors agree to exclude another business. This restrains trade and is illegal under the Sherman Antitrust Act."},{id:"q34",category:"Ethics",question:"Which is NOT a duty under the NAR Code of Ethics?",options:["Honesty in advertising","Duty to clients","Guaranteeing property appreciation","Duty to other REALTORS®"],correctIndex:2,explanation:"The Code of Ethics emphasizes honesty, fiduciary duties, and professional cooperation. No one can guarantee future property values or appreciation."},{id:"q35",category:"Associations",question:"What is the purpose of local REALTOR® boards in Massachusetts?",options:["Issue real estate licenses","Set commission rates for the area","Provide local MLS access, education, and networking","Approve all real estate transactions"],correctIndex:2,explanation:"Local boards provide MLS access, continuing education, networking opportunities, and local market resources. They do not issue licenses or set commission rates."},{id:"q36",category:"Fair Housing",question:"Which is NOT a protected class under the Federal Fair Housing Act?",options:["Religion","Familial status","Sexual orientation","Employment status"],correctIndex:3,explanation:"Employment status is NOT a federally protected class. The seven protected classes are: race, color, religion, national origin, sex, familial status, and disability."},{id:"q37",category:"Fair Housing",question:'An agent suggests to a buyer that they would be "happier" in a different neighborhood. This is:',options:["Good customer service","Steering (illegal)","Required due diligence","Personal opinion sharing"],correctIndex:1,explanation:"Steering is illegal under fair housing law. Agents cannot guide clients toward or away from neighborhoods based on protected class characteristics."},{id:"q38",category:"Fair Housing",question:"What is the penalty for violating the Fair Housing Act?",options:["Warning letter only","Up to $100,000 fine for first offense","Community service","No penalty if unintentional"],correctIndex:1,explanation:"First-time violations can result in fines up to $100,000, plus civil damages. Subsequent violations carry even higher penalties. Intent is not required for liability."},{id:"q39",category:"Property Valuation",question:"Which valuation approach is most appropriate for a new custom home?",options:["Sales comparison approach","Income approach","Cost approach","Depreciation approach"],correctIndex:2,explanation:"The cost approach is best for new construction or unique properties. It calculates land value plus cost to build new, minus depreciation."},{id:"q40",category:"Property Valuation",question:'In a CMA, what is a "comp"?',options:["Compensation to the agent","Comparable recently sold property","Computer analysis","Complimentary service"],correctIndex:1,explanation:'A "comp" is a comparable property - similar properties that recently sold in the area, used to estimate the subject property\'s value.'},{id:"q41",category:"Financing",question:"A buyer has a $100,000 down payment on a $500,000 home. What is the LTV ratio?",options:["20%","50%","80%","100%"],correctIndex:2,explanation:"LTV = Loan Amount / Property Value. Loan is $400,000 ($500k - $100k down). $400k / $500k = 0.80 or 80% LTV."},{id:"q42",category:"Financing",question:"What typically happens to PMI once the LTV drops below 80%?",options:["It increases","It can be removed","It becomes permanent","Nothing changes"],correctIndex:1,explanation:"PMI can typically be removed once the loan balance drops to 80% of the home's value through payments or appreciation. Borrower must request removal."},{id:"q43",category:"Financing",question:"What is an ARM margin?",options:["The lender's profit","A fixed percentage added to the index rate","The down payment amount","The closing cost"],correctIndex:1,explanation:"The margin is a fixed percentage that the lender adds to the index rate to determine the ARM interest rate. Example: 2% index + 2.5% margin = 4.5% rate."},{id:"q44",category:"Contracts",question:"What are the four essential elements of a valid contract?",options:["Offer, acceptance, consideration, competent parties","Price, property, people, payment","Buy, sell, sign, close","Agent, broker, buyer, seller"],correctIndex:0,explanation:"The four essentials are: (1) Offer and Acceptance (mutual agreement), (2) Consideration (something of value exchanged), (3) Legal Purpose, and (4) Competent Parties."},{id:"q45",category:"Contracts",question:"A contract signed by a 16-year-old is:",options:["Valid and enforceable","Void","Voidable by the minor","Illegal"],correctIndex:2,explanation:"Contracts with minors (under 18) are voidable by the minor. The minor can choose to void the contract, but the adult party cannot."},{id:"q46",category:"Property Rights",question:"A built-in dishwasher is considered:",options:["Personal property","Real property (fixture)","Temporary equipment","Seller's choice"],correctIndex:1,explanation:"Built-in appliances are fixtures (real property) because they are permanently attached. They transfer with the home unless specifically excluded in the contract."},{id:"q47",category:"Property Rights",question:"What is an encumbrance?",options:["A valuable property feature","Any claim or liability that affects property value","A type of deed","Property insurance"],correctIndex:1,explanation:"An encumbrance is any claim, lien, charge, or liability (like easements, liens, restrictions) that affects or limits the property interest or value."},{id:"q48",category:"Zoning",question:"A homeowner wants to build a deck 5 feet from the property line, but zoning requires 10 feet. They need:",options:["A building permit only","A variance","An easement","Nothing, they can proceed"],correctIndex:1,explanation:"A variance is permission to deviate from zoning requirements due to unique hardship. It's granted by the local zoning board of appeals."},{id:"q49",category:"Zoning",question:"Which allows the broadest use of property?",options:["R-1 (Single-family residential)","R-2 (Multi-family residential)","C-1 (Commercial)","I (Industrial)"],correctIndex:3,explanation:"Industrial zoning typically allows the broadest uses, including industrial, commercial, and often residential. Residential zoning is the most restrictive."},{id:"q50",category:"Environmental",question:"Who is responsible for lead paint disclosure on a pre-1978 home?",options:["Only the seller","Only the buyer's agent","The seller and both agents","The home inspector"],correctIndex:2,explanation:"Both the seller and all agents involved must provide lead paint disclosure for pre-1978 homes. Buyers must receive the EPA pamphlet and have 10 days for testing."},{id:"q51",category:"Environmental",question:"What is the primary concern with underground storage tanks (USTs)?",options:["They take up space","Potential soil and water contamination from leaks","They are expensive to install","They are aesthetically unpleasing"],correctIndex:1,explanation:"Old USTs (like oil tanks) can leak and contaminate soil and groundwater, creating expensive cleanup liability. Many states require disclosure and testing."},{id:"q52",category:"Insurance",question:"What is the main difference between HO-2 and HO-3 homeowner's insurance?",options:["HO-3 covers more perils (all-risk for dwelling)","HO-2 is more expensive","HO-3 is for renters","No difference"],correctIndex:0,explanation:'HO-3 is "all-risk" (open perils) for the dwelling - covers everything except specifically excluded perils. HO-2 only covers named perils listed in the policy.'},{id:"q53",category:"Insurance",question:"Flood insurance is provided through:",options:["Private insurance companies only","FEMA's National Flood Insurance Program","State governments","Not available"],correctIndex:1,explanation:"Most flood insurance is provided through FEMA's National Flood Insurance Program (NFIP), though private flood insurance is becoming more available."},{id:"q54",category:"Tax",question:"In a 1031 exchange, how many days does the investor have to identify replacement properties?",options:["30 days","45 days","90 days","180 days"],correctIndex:1,explanation:"45 days to identify potential replacement properties, and 180 days total to close on the new property. These are strict IRS deadlines that cannot be extended."},{id:"q55",category:"Tax",question:"A couple sells their primary home for a $600,000 gain after living there 3 years. How much is taxable?",options:["$0","$100,000","$300,000","$600,000"],correctIndex:1,explanation:"Married couples can exclude $500,000 of capital gains if they lived in the home 2 of the last 5 years. $600,000 gain - $500,000 exclusion = $100,000 taxable."},{id:"q56",category:"Agency",question:"What is subagency?",options:["A junior agent","When a cooperating broker represents the listing broker's client (seller)","An unlicensed assistant","A backup agent"],correctIndex:1,explanation:"Subagency means a cooperating broker works for the listing broker and owes fiduciary duties to the seller, not the buyer. Less common now due to buyer agency."},{id:"q57",category:"Agency",question:"What are the fiduciary duties owed to a client? (OLD-CAR)",options:["Obedience, Loyalty, Disclosure, Confidentiality, Accounting, Reasonable care","Openness, Likability, Determination, Communication","Only honesty is required","Just do your best"],correctIndex:0,explanation:"The six fiduciary duties (OLD-CAR): Obedience, Loyalty, Disclosure, Confidentiality, Accounting, and Reasonable care/skill. All owed to the principal/client."},{id:"q58",category:"Appraisal",question:'What is the "subject property" in an appraisal?',options:["Any comparable property","The property being appraised","The most expensive comp","The appraiser's own property"],correctIndex:1,explanation:'The "subject property" is the specific property being appraised and valued. Comparables are other properties used for comparison to determine the subject\'s value.'},{id:"q59",category:"Appraisal",question:"In the sales comparison approach, if a comp has a feature the subject lacks, you:",options:["Add value to the subject","Subtract value from the comp","Ignore the difference","Add value to the comp"],correctIndex:1,explanation:'CBS: "Comp Better, Subtract" - If the comp has something better than the subject, subtract value from the comp to make it more comparable to the subject.'},{id:"q60",category:"Inspection",question:"A home inspection reveals termite damage. What happens next?",options:["Sale automatically cancelled","Buyer can request repairs, credit, or price reduction (if within inspection period)","Seller must repair everything","Buyer must accept property as-is"],correctIndex:1,explanation:"Within the inspection contingency period, buyer can request repairs, negotiate credits, request price reduction, or walk away. Seller can accept, counter, or refuse."},{id:"q61",category:"Inspection",question:"Which is typically NOT included in a standard home inspection?",options:["Roof condition","Radon testing","HVAC system","Plumbing"],correctIndex:1,explanation:"Radon testing, pest inspections, lead paint testing, and septic/well tests are separate specialized inspections, not included in standard home inspections."},{id:"q62",category:"Settlement",question:"When must the Closing Disclosure be provided to the borrower?",options:["At the closing table","At least 3 business days before closing","Within 3 days after closing","Anytime before closing"],correctIndex:1,explanation:"TRID rules require the Closing Disclosure be provided at least 3 business days before closing, giving borrowers time to review final loan terms and costs."},{id:"q63",category:"Settlement",question:"Who typically pays the buyer agent's commission?",options:["Always the buyer","Always the seller","Negotiable - typically seller but can be buyer","The lender"],correctIndex:2,explanation:"Commission payment is negotiable. Traditionally, the seller paid both agents' commissions, but under 2025 changes, the buyer may pay their own agent directly."},{id:"q64",category:"Deeds",question:"Which deed provides the LEAST protection to the buyer?",options:["General warranty deed","Special warranty deed","Quitclaim deed","Bargain and sale deed"],correctIndex:2,explanation:"A quitclaim deed provides NO warranties or guarantees. The seller transfers only whatever interest they may have, with zero protection to the buyer."},{id:"q65",category:"Deeds",question:"What must a deed contain to be valid?",options:["Grantor signature, grantee, legal description, consideration","Just a signature","Notarization only","Witness signatures"],correctIndex:0,explanation:"Essential deed elements: competent grantor, grantee identified, words of conveyance, legal description, grantor signature, and delivery/acceptance. (Notarization required for recording but not validity)"},{id:"q66",category:"Bonds & Licensing",question:"What is the purpose of E&O (Errors and Omissions) insurance?",options:["Protects against property damage","Protects against professional negligence claims","Required for all home sales","Covers criminal violations"],correctIndex:1,explanation:"E&O insurance protects real estate professionals against claims of negligence, mistakes, or failure to perform duties. It covers legal defense costs and damages awarded."},{id:"q67",category:"Bonds & Licensing",question:"Who can make a claim against a broker's surety bond?",options:["Anyone who feels wronged","Only other brokers","Parties who suffered financial harm due to broker's legal violations","The state only"],correctIndex:2,explanation:"Surety bonds protect the public. Injured parties who suffered financial harm due to the broker violating real estate laws can make claims against the bond for compensation."},{id:"q68",category:"Protection Clauses",question:"A buyer's financing contingency expires in 30 days. On day 35, they still don't have loan approval. What happens?",options:["Contingency automatically extends","Seller can cancel and keep deposit","Nothing changes","Buyer gets extra time automatically"],correctIndex:1,explanation:"Once a contingency deadline passes without the buyer exercising or removing it, the buyer typically loses that protection. Seller can cancel the contract and may keep the deposit."},{id:"q69",category:"Protection Clauses",question:"What is the main risk for sellers accepting a home sale contingency?",options:["Higher commission","Their property is tied up while buyer tries to sell their home","Lower sale price","More inspections required"],correctIndex:1,explanation:"Home sale contingencies tie up the property (taking it off market) while the buyer attempts to sell their current home, which could take months. This is why kick-out clauses exist."},{id:"q70",category:"Protection Clauses",question:"A seller accepts an offer with a home sale contingency and a 72-hour kick-out clause. A better offer comes in. What happens?",options:["Seller must wait for first buyer to sell","Seller can immediately accept the new offer","First buyer has 72 hours to remove contingency or lose the deal","New buyer must wait"],correctIndex:2,explanation:"A kick-out clause allows the seller to notify the first buyer that they have 72 hours (or specified time) to remove the contingency or the seller can accept the new offer."},{id:"q71",category:"MA Law",question:"Under MA Chapter 93A, what can consumers receive for WILLFUL unfair practices?",options:["Single damages only","Double damages","Triple damages (treble damages)","No damages, just an apology"],correctIndex:2,explanation:"Massachusetts Chapter 93A allows for triple damages (treble damages) plus attorney fees for willful or knowing violations of unfair or deceptive practices."},{id:"q72",category:"MA Law",question:"In Massachusetts, who enforces smoke detector compliance before closing?",options:["Real estate agent","Local fire department","Home inspector","Lender"],correctIndex:1,explanation:"The local fire department inspects and issues a certificate of compliance for smoke and carbon monoxide detectors. This certificate is required before closing in Massachusetts."},{id:"q73",category:"MA Law",question:"What is the penalty for failing to provide lead paint disclosure on a pre-1978 home?",options:["Warning letter only","Up to $10,000 fine and possible triple damages","No penalty if unintentional","License suspension only"],correctIndex:1,explanation:"Federal law provides for penalties up to $11,000+ per violation. Sellers can also be liable for triple damages if buyer's children are harmed by lead paint."},{id:"q74",category:"Trust Accounts",question:'What is "commingling" in real estate?',options:["Mixing client funds with broker's personal or business funds","Having multiple clients","Working with multiple brokerages","Dual agency"],correctIndex:0,explanation:"Commingling is illegally mixing client funds (deposits, rents) with the broker's own money. All client funds must be kept in a separate trust account."},{id:"q75",category:"Trust Accounts",question:"A broker receives a $5,000 earnest money deposit. What must they do?",options:["Deposit it in their business checking account","Keep it in cash","Deposit it in a trust account within specified timeframe (typically 1-3 business days)","Give it directly to the seller"],correctIndex:2,explanation:"Earnest money must be promptly deposited into a trust account (usually within 1-3 business days per state law). It cannot be commingled with broker's personal funds."},{id:"q76",category:"Continuing Education",question:"How many CE hours are required for Massachusetts license renewal?",options:["6 hours every year","12 hours every 2 years","24 hours every 2 years","No CE required in MA"],correctIndex:1,explanation:"Massachusetts requires 12 hours of approved continuing education every 2 years for both salespersons and brokers to maintain an active license."},{id:"q77",category:"Continuing Education",question:"An agent's license expired 3 months ago and they haven't completed CE. What happens?",options:["Nothing, they can still practice","License is inactive - cannot practice until CE completed and reactivated","Automatic 6-month extension","CE requirement is waived"],correctIndex:1,explanation:"Once a license expires without completed CE, it becomes inactive. The agent cannot practice real estate until completing CE requirements and paying reactivation fees."},{id:"q78",category:"Licensing",question:"What is the typical cost for Massachusetts salesperson license renewal (not including CE courses)?",options:["$50-75","$150-200","$500-600","$1,000+"],correctIndex:1,explanation:"Massachusetts license renewal fees are approximately $150-200 for salespersons. This does not include CE course costs, which are additional, or association/MLS dues."},{id:"q79",category:"Broker Requirements",question:"How many years of experience are required to become a broker in Massachusetts?",options:["1 year","2 years","3 years within the last 5 years","5 years"],correctIndex:2,explanation:"Massachusetts requires 3 years of active experience as a licensed salesperson (within the past 5 years), plus completion of a 40-hour broker pre-license course and passing the broker exam."},{id:"q80",category:"Broker Requirements",question:"What is the main advantage of having a broker license over a salesperson license?",options:["Lower fees","Can work independently and own a brokerage","No CE requirements","Higher commission guaranteed"],correctIndex:1,explanation:"Brokers can work independently, own brokerages, and supervise other agents. Salespersons must work under a supervising broker and cannot operate independently."},{id:"q81",category:"Certifications",question:"What does the GRI designation stand for?",options:["General Real Estate Information","Graduate, REALTOR® Institute","Guaranteed Return Investment","Great Residential Income"],correctIndex:1,explanation:"GRI stands for Graduate, REALTOR® Institute. It's a 60+ hour advanced education program covering legal issues, technology, marketing, and professional standards."},{id:"q82",category:"Certifications",question:"Which designation is specifically focused on representing buyers?",options:["CRS","GRI","ABR (Accredited Buyer's Representative)","SRES"],correctIndex:2,explanation:"ABR (Accredited Buyer's Representative) is specialized training for representing buyers, covering buyer agency, loyalty, market analysis, and negotiation - especially valuable post-2025 changes."},{id:"q83",category:"Certifications",question:"Approximately what percentage of REALTORS® hold the CRS designation?",options:["3%","25%","50%","75%"],correctIndex:0,explanation:"Only about 3% of REALTORS® hold the CRS (Certified Residential Specialist) designation. It's the premier credential for residential sales, requiring production minimums and advanced training."},{id:"q84",category:"Certifications",question:"Are professional designations like GRI, CRS, and ABR mandatory in Massachusetts?",options:["Yes, must have at least one","Yes, GRI is mandatory","No, all are optional but recommended","Yes, for brokers only"],correctIndex:2,explanation:"All professional designations are optional. They demonstrate expertise and commitment, help attract clients, and can justify higher commission splits, but they are not legally required."},{id:"q85",category:"Mandatory Requirements",question:"Which of the following is NOT mandatory to maintain an active MA license?",options:["Complete 12 hours CE every 2 years","Pay renewal fees on time","Have NAR/MAR membership","Work under a supervising broker (for salespersons)"],correctIndex:2,explanation:"NAR/MAR membership is not legally mandatory, though most brokerages require it for MLS access. CE completion, fee payment, and broker supervision (for salespersons) are mandatory."},{id:"q86",category:"Mandatory Requirements",question:"Is E&O insurance legally required in Massachusetts?",options:["Yes, for all licensees","Yes, but only for brokers","No, but many brokerages require it","Only for first-year agents"],correctIndex:2,explanation:"E&O insurance is NOT legally required by Massachusetts, but most brokerages require it as a condition of affiliation. It's highly recommended to protect against negligence claims."},{id:"q87",category:"Broker Responsibilities",question:"Who is responsible if an affiliated agent violates real estate law?",options:["Only the agent","Only the broker","Both the agent and the supervising broker","Neither, if unintentional"],correctIndex:2,explanation:"Both the agent and broker can be held responsible. The broker has supervisory responsibility for all affiliated agents and must ensure they follow laws and proper procedures."},{id:"q88",category:"Broker Responsibilities",question:"What must a broker do with all contracts their agents prepare?",options:["Nothing, agents handle their own","Review and approve them","File them with the state","Only review if problems arise"],correctIndex:1,explanation:"Brokers must review and approve all contracts prepared by their agents. This is part of their supervisory responsibility to ensure legal compliance and protect clients."},{id:"q89",category:"Licensing",question:"Can you practice real estate while your license transfer between brokers is processing?",options:["Yes, with written permission","Yes, for existing clients only","No, cannot practice during transfer","Yes, if under 30 days"],correctIndex:2,explanation:"You cannot practice real estate during a license transfer. The license must be officially transferred to the new broker before you can conduct any real estate activities under that broker."},{id:"q90",category:"Professional Development",question:"What is a key benefit of earning professional certifications like GRI or ABR?",options:["Avoid CE requirements","Automatically higher commission","Increased credibility and client attraction","No license fees"],correctIndex:2,explanation:"Professional certifications increase your credibility, demonstrate expertise, attract more clients, and can help justify higher commission splits. They show commitment to professional excellence but don't waive other requirements."},{id:"q91",category:"Insurance",question:"What is the typical annual cost of E&O insurance for a real estate agent?",options:["$100-200","$300-800","$2,000-3,000","$5,000+"],correctIndex:1,explanation:"E&O insurance typically costs $300-800 per year for agents, depending on coverage limits, deductible, claims history, and transaction volume. Group rates through associations are often cheaper."},{id:"q92",category:"Insurance",question:"What does E&O insurance NOT cover?",options:["Professional negligence","Errors in paperwork","Intentional fraud or criminal acts","Failure to disclose defects"],correctIndex:2,explanation:"E&O insurance does NOT cover intentional acts, fraud, punitive damages, or criminal violations. It only covers negligent acts, errors, and omissions made in good faith."},{id:"q93",category:"Insurance",question:"What is the difference between claims-made and occurrence E&O policies?",options:["No difference, just different names","Claims-made covers when claim is filed; occurrence covers when incident happened","Claims-made is cheaper","Occurrence requires tail coverage"],correctIndex:1,explanation:"Claims-made covers claims filed during the policy period (requires tail coverage after). Occurrence covers incidents that occurred during policy (more expensive but no tail needed)."},{id:"q94",category:"Insurance",question:"You're retiring and canceling your claims-made E&O policy. What should you buy?",options:["Nothing needed","General liability insurance","Tail coverage (extended reporting period)","A new occurrence policy"],correctIndex:2,explanation:"Tail coverage provides extended reporting for claims filed after your policy ends for incidents that occurred while insured. Essential when retiring or switching carriers. Costs 1.5-3x annual premium."},{id:"q95",category:"Insurance",question:"What are standard E&O coverage limits recommended for agents?",options:["$100K/$100K","$500K/$500K","$1M/$1M","$10M/$10M"],correctIndex:2,explanation:"$1M per claim and $1M aggregate (total annual) is standard. $500K is minimum, $2M recommended for high-volume agents. Higher limits provide better protection against large lawsuits."},{id:"q96",category:"Insurance",question:"An agent makes an error but hasn't been sued yet. Should they report it to E&O insurance?",options:["No, wait until lawsuit is filed","Yes, report immediately - policies require timely notification","Only if damages exceed $10,000","Only if client complains"],correctIndex:1,explanation:'Report ANY potential claim immediately. Most policies require "timely notification" of errors or circumstances that could lead to claims. Waiting can result in denied coverage.'},{id:"q97",category:"Insurance",question:"What is general liability insurance for real estate agents?",options:["Same as E&O insurance","Covers bodily injury and property damage during business operations","Only for brokers","Covers professional errors"],correctIndex:1,explanation:"General liability covers bodily injury and property damage (like client tripping at a showing). Separate from E&O which covers professional mistakes. Costs $300-600/year."},{id:"q98",category:"Insurance",question:"What is cyber liability insurance for real estate?",options:["Covers website hosting","Covers data breaches and cyberattacks","Not needed for real estate","Same as E&O insurance"],correctIndex:1,explanation:"Cyber liability covers data breaches, hacking, and identity theft involving client personal information (SSNs, financial data). Costs $500-2,000/year. Increasingly important with digital transactions."},{id:"q99",category:"Insurance",question:"What is a fidelity bond in real estate?",options:["Same as E&O insurance","Protects against employee theft or dishonest acts","Required for all agents","Covers client lawsuits"],correctIndex:1,explanation:"Fidelity bonds protect against employee theft or dishonest acts (stealing funds, forging documents). Required if broker has employees. Different from E&O. Costs $200-500/year."},{id:"q100",category:"Insurance",question:"A broker has 20 independent contractor agents. Do they need workers compensation insurance?",options:["Yes, required for all agents","No, ICs are not employees - workers comp not required","Yes, but only for full-time agents","Only if requested by agents"],correctIndex:1,explanation:"Independent contractors are not employees, so workers compensation is not required for them. Only needed if broker has W-2 employees. ICs are responsible for their own insurance."},{id:"q101",category:"Insurance",question:"What is a typical E&O insurance deductible?",options:["$100-250","$1,000-5,000","$25,000-50,000","No deductibles on E&O"],correctIndex:1,explanation:"Common deductibles are $1,000-5,000 per claim. Higher deductibles = lower premiums. Deductible applies to both defense costs and any settlements or judgments."},{id:"q102",category:"Insurance",question:"Can an independent contractor agent buy their own E&O policy?",options:["No, must be covered by broker only","Yes, for extra protection beyond broker's coverage","Only if broker doesn't have E&O","Not allowed in Massachusetts"],correctIndex:1,explanation:"Yes, agents can purchase individual E&O policies ($300-600/year) for extra protection beyond the broker's coverage or if changing brokerages. Not required but increasingly common."},{id:"q103",category:"Insurance",question:"What is prior acts coverage in E&O insurance?",options:["Coverage for criminal acts","Coverage for incidents before current policy start date","Coverage for future claims","Not applicable to real estate"],correctIndex:1,explanation:'Prior acts coverage extends back before your current policy start date. "Full prior acts" has no retroactive date and covers all past work. Critical when switching carriers.'},{id:"q104",category:"Insurance",question:"Total annual insurance costs for a real estate broker's office typically run:",options:["$500-1,000","$2,000-5,000+","$10,000-20,000","$50,000+"],correctIndex:1,explanation:"Broker office insurance (E&O, general liability, commercial property, cyber liability, fidelity bond, etc.) typically costs $2,000-5,000+ annually depending on coverage limits and business size."},{id:"q105",category:"Insurance",question:"Which situation would E&O insurance typically cover?",options:["Intentionally hiding property defects","Missing a deadline that causes client financial loss","Embezzling client funds","Criminal fraud"],correctIndex:1,explanation:"E&O covers negligent acts like missing deadlines, errors in paperwork, failure to disclose (if unintentional), and breach of duty. It does NOT cover intentional acts, fraud, or criminal violations."},{id:"q106",category:"Multi-State Licensing",question:"Can a Massachusetts licensed agent practice real estate in Rhode Island without additional licensing?",options:["Yes, New England states allow cross-border practice","No, must obtain a separate RI license","Yes, if within 50 miles of border","Only with broker permission"],correctIndex:1,explanation:"Real estate licenses are state-specific. You must obtain a separate license in each state where you practice, even neighboring states. However, RI offers reciprocity making it easier."},{id:"q107",category:"Multi-State Licensing",question:"What is license reciprocity?",options:["Automatic licensing in all states","Reduced requirements for out-of-state licensees (waiving courses or exams)","Same as having two licenses","Only for brokers"],correctIndex:1,explanation:"Reciprocity means a state offers reduced licensing requirements (like waiving the national exam or pre-license course) for licensees from other states. Not all states have reciprocity agreements."},{id:"q108",category:"Rhode Island Licensing",question:"A MA agent wants a Rhode Island license. What must they do?",options:["Nothing, automatic reciprocity","Pass RI state exam only (no course or national exam required)","Complete full 90-hour course","Wait 5 years"],correctIndex:1,explanation:"RI offers reciprocity for MA agents. Only need to pass the RI state-specific exam (no pre-license course or national exam required). Fastest neighboring state option."},{id:"q109",category:"New Hampshire Licensing",question:"To get a NH license, a MA agent must:",options:["Nothing, NH recognizes MA licenses","Pass NH state exam and complete 40-hour NH course","Move to New Hampshire","Only pass national exam"],correctIndex:1,explanation:"NH offers reciprocity but requires passing the NH state law exam and completing a 40-hour NH-specific course. National exam is waived. Popular for MA agents in border areas."},{id:"q110",category:"New York Licensing",question:"Does New York offer reciprocity with Massachusetts?",options:["Yes, full reciprocity","Yes, partial reciprocity","No, must complete full NY licensing requirements from scratch","Only for brokers"],correctIndex:2,explanation:"NY does NOT offer reciprocity with MA. Must complete the full 75-hour NY pre-license course and pass both national and NY state exams. Most difficult neighboring state to get licensed in."},{id:"q111",category:"Connecticut Licensing",question:"What does Connecticut require from MA agents seeking licensure?",options:["Nothing, automatic reciprocity","CT state exam only and 60-hour CT course","Just a background check","Must retake national exam"],correctIndex:1,explanation:"CT offers reciprocity by waiving the national exam portion, but requires passing the CT state exam and completing a 60-hour CT-specific course. Fees typically $200-300."},{id:"q112",category:"Multi-State Licensing",question:"What is the typical total cost to obtain a second state license through reciprocity?",options:["$50-100","$450-975","$2,000-3,000","$10,000+"],correctIndex:1,explanation:"Costs include: application fees ($100-300), state exam ($50-100), required courses ($200-400 if needed), background checks ($50-100), and fingerprints ($50-75). Total: $450-975 per state."},{id:"q113",category:"Multi-State Licensing",question:"An agent is licensed in both MA and NH. How many CE hours must they complete?",options:["12 hours total (MA requirement only)","CE hours for EACH state separately","Whichever state requires more","No CE required for second state"],correctIndex:1,explanation:"Must complete CE requirements for EACH state separately. MA requires 12 hrs/2 years, NH has its own requirements. Can be 12-24+ hours annually across multiple states."},{id:"q114",category:"Multi-State Licensing",question:"Can an agent work for different brokers in different states?",options:["No, must have same broker everywhere","Yes, but must have a licensed broker in EACH state","Only if states are adjacent","Not allowed"],correctIndex:1,explanation:"Yes, but each license must be affiliated with a broker licensed in that state. Can work for same broker's multi-state offices or completely different brokers per state."},{id:"q115",category:"Multi-State Licensing",question:"Which neighboring state is easiest for MA agents to get licensed in?",options:["New York","Connecticut","Rhode Island (just state exam required)","All equally difficult"],correctIndex:2,explanation:"Rhode Island is fastest/easiest - only requires passing RI state exam with no additional courses. NH and VT are also relatively easy. NY has NO reciprocity (hardest)."},{id:"q116",category:"Multi-State Licensing",question:"Why would a MA agent get licensed in New Hampshire?",options:["Required for all MA agents","To serve border towns, vacation homes, and expand market area","NH licenses are cheaper","No reason"],correctIndex:1,explanation:"Popular reasons: serve MA/NH border towns, access vacation/second-home market (lakes, mountains), help relocating clients, expand income potential, and competitive advantage."},{id:"q117",category:"Multi-State Licensing",question:"Can a MA broker open a brokerage in Connecticut?",options:["Yes, MA broker license works in all New England","Yes, if they obtain a CT broker license","No, never allowed","Only after 10 years"],correctIndex:1,explanation:"Yes, but must obtain a CT broker license meeting all CT broker requirements (experience, courses, exams). Must comply with CT regulations and maintain separate trust accounts."},{id:"q118",category:"Vermont Licensing",question:"Vermont offers reciprocity to MA agents. What is typically required?",options:["Nothing, automatic","Pass VT state exam and background check","Complete 90-hour course","Move to Vermont"],correctIndex:1,explanation:"VT offers reciprocity - requires passing VT state-specific exam (waives national) and background check. Fees typically $100-200. Less common due to smaller market but simpler process."},{id:"q119",category:"Multi-State Licensing",question:"What is a multi-state broker?",options:["A broker who travels between states","A broker licensed in multiple states who can supervise and operate in each","Automatic status after 5 years","Only for large companies"],correctIndex:1,explanation:"A multi-state broker holds broker licenses in multiple states, allowing them to supervise agents and operate brokerages in each state. Must meet all broker requirements for each state separately."},{id:"q120",category:"Multi-State Licensing",question:"Do you need separate E&O insurance for each state license?",options:["No, one policy covers all states","Yes, must have separate policy for each state","Depends on the policy - verify coverage area with carrier","E&O not required for second states"],correctIndex:2,explanation:"Depends on your E&O policy. Some cover all states where you're licensed, others are state-specific. ALWAYS verify with your insurance carrier before practicing in additional states to ensure coverage."},{id:"q121",category:"Referrals",question:"What is a typical referral fee percentage in real estate?",options:["5-10%","20-35%","50%","75%"],correctIndex:1,explanation:"Referral fees typically range from 20-35% of the receiving agent's commission. Example: Receiving agent earns $10,000, referring agent receives $2,000-3,500. Percentage is negotiable between agents."},{id:"q122",category:"Referrals",question:"Can a MA agent receive a referral fee from a California transaction where they're not licensed?",options:["No, never allowed","Yes, if licensed in MA and referring from MA","Only if they visit the property","Only with special permission"],correctIndex:1,explanation:"Generally YES - licensed agents can receive referral fees from states where they're not licensed, as long as they're licensed somewhere and referring from their home state. The receiving agent must be CA-licensed."},{id:"q123",category:"Referrals",question:"Can an unlicensed person receive a referral fee for sending you business?",options:["Yes, if under $500","Yes, if they sign a contract","No, only licensed agents can receive referral fees","Yes, but only gift cards"],correctIndex:2,explanation:"NO. RESPA and state laws prohibit paying referral fees to unlicensed persons. Only licensed real estate professionals can receive compensation for referrals. Violations can result in fines and license suspension."},{id:"q124",category:"Referrals",question:"What should be included in a referral agreement?",options:["Just verbal agreement is fine","Names, client info, referral fee %, payment terms, signatures","Only the referral percentage","Not necessary if you trust them"],correctIndex:1,explanation:"Written referral agreements should include: both agents' names, client information, property details (if known), referral fee percentage, payment terms, and signatures. Should be signed BEFORE closing."},{id:"q125",category:"Gifts to Clients",question:"Can real estate agents give closing gifts to clients?",options:["No, never allowed under RESPA","Yes, reasonable gifts ($100 or less recommended) are acceptable","Only to sellers, not buyers","Only branded marketing items"],correctIndex:1,explanation:"YES - reasonable closing gifts are acceptable. Keep gifts under $100 (recommended), don't use to induce business, and avoid cash. Gift baskets, plants, and home items are common and appropriate."},{id:"q126",category:"Gifts to Clients",question:"What does RESPA Section 8 prohibit?",options:["All gifts to anyone","Kickbacks and unearned fees in exchange for referrals","Marketing expenses","Closing gifts"],correctIndex:1,explanation:"RESPA Section 8 prohibits kickbacks and unearned fees - gifts given in exchange for referrals or to induce business from settlement service providers. Violations carry $10,000+ fines and possible jail time."},{id:"q127",category:"Gifts to Clients",question:"Which is a safe client gift for real estate agents?",options:["Cash","Gift card to home improvement store","Gift basket or plant under $100","Paying their utility bill"],correctIndex:2,explanation:"Gift baskets, plants, and home items under $100 are safe and appropriate. Avoid cash or cash equivalents (gift cards can be seen as cash). Marketing items under $10 are always safe."},{id:"q128",category:"Compensation Rules",question:"Can you pay your unlicensed assistant a percentage of each transaction?",options:["Yes, if they work hard","Yes, up to 10%","No, must be hourly or salary only","Yes, with broker approval"],correctIndex:2,explanation:"NO. Unlicensed assistants must be paid hourly wage or salary only, never commission or transaction-based pay. Only licensed agents can receive commission-based compensation. This is a licensing law violation."},{id:"q129",category:"Compensation Rules",question:"What CAN unlicensed assistants legally do?",options:["Show properties","Negotiate contracts","Schedule appointments and prepare marketing materials","Give pricing advice"],correctIndex:2,explanation:"Unlicensed assistants can handle administrative tasks: scheduling, phone calls, marketing prep, file maintenance, closing coordination. CANNOT: show properties, negotiate, discuss terms, or anything requiring a license."},{id:"q130",category:"Compensation Rules",question:'Your friend refers a client who buys a home. Can you pay them a "finder\'s fee"?',options:["Yes, up to $500","Yes, any amount is fine","No, if they're unlicensed - can only give thank-you gift","Yes, but only after closing"],correctIndex:2,explanation:"NO cash compensation if unlicensed. Only licensed agents can receive referral fees. You can give a thank-you gift (not cash), but nothing tied to the transaction. RESPA prohibits paying unlicensed persons for referrals."},{id:"q131",category:"Referrals",question:"Who pays the referral fee to the referring agent?",options:["The buyer or seller","The receiving agent's broker","The title company","The referring agent pays themselves"],correctIndex:1,explanation:"The receiving agent's broker pays the referring agent's broker (from the receiving agent's commission), who then pays the referring agent. Not added to client costs - comes from agent's earned commission."},{id:"q132",category:"Referrals",question:"Should referral arrangements be disclosed to clients?",options:["No, it's confidential between agents","Only if the client asks","Yes, best practice for transparency even if not legally required","Never disclose"],correctIndex:2,explanation:"Best practice: YES, disclose referral arrangements to clients for transparency. Some states require it. Even when not required, disclosure builds trust and avoids conflicts of interest. Include in agency disclosures."},{id:"q133",category:"Gifts to Clients",question:"Can you give a buyer a commission rebate at closing?",options:["Yes, always allowed","No, never allowed","Depends on state law and lender approval","Only in luxury transactions"],correctIndex:2,explanation:"Depends on state law and lender approval. Some states allow commission rebates, others prohibit them. Massachusetts allows with proper disclosure. Must inform lender as it may affect financing calculations."},{id:"q134",category:"Compensation Rules",question:"Can MA and California brokers split a commission on a cross-state transaction?",options:["No, different states cannot cooperate","Yes, licensed brokers can cooperate across state lines","Only through a national franchise","Only for commercial properties"],correctIndex:1,explanation:"YES - licensed brokers can cooperate and split commissions across state lines. Both must be licensed in their respective states. Common in referrals and relocations. Requires written agreement."},{id:"q135",category:"Referrals",question:"When should a referral agreement be signed?",options:["After closing","When commission check arrives","Before the transaction closes","Doesn't need to be written"],correctIndex:2,explanation:"Referral agreements should be signed BEFORE the transaction closes, ideally when the referral is made. Having a written agreement protects both parties and clarifies terms before any disputes arise."},{id:"q136",category:"Electronic Signatures",question:"When was the federal E-Sign Act passed making electronic signatures legal?",options:["1995","2000","2010","2020"],correctIndex:1,explanation:"The Electronic Signatures in Global and National Commerce Act (E-Sign Act) was passed in 2000, making electronic signatures legal and binding in interstate and foreign commerce."},{id:"q137",category:"Electronic Signatures",question:"Are electronic signatures valid for real estate contracts in Massachusetts?",options:["No, real estate requires wet signatures","Yes, under E-Sign Act and UETA","Only for leases","Only with attorney approval"],correctIndex:1,explanation:"YES - electronic signatures are legal and binding for real estate contracts under the federal E-Sign Act (2000) and state UETA laws. Commonly used for offers, contracts, and disclosures."},{id:"q138",category:"Electronic Signatures",question:"What does UETA stand for?",options:["Universal Electronic Transfer Act","Uniform Electronic Transactions Act","United Estate Transfer Agreement","Universal E-Signature Trading Act"],correctIndex:1,explanation:"UETA stands for Uniform Electronic Transactions Act - state-level law (adopted by most states) that validates electronic signatures and records, working alongside the federal E-Sign Act."},{id:"q139",category:"Do Not Call",question:"When was the Do Not Call Registry created?",options:["1995","2000","2003","2010"],correctIndex:2,explanation:"The Do Not Call Registry was created in 2003 with the Do Not Call Improvement Act. It was further strengthened in 2007 to enhance consumer protections against telemarketing."},{id:"q140",category:"Do Not Call",question:"How often must real estate agents check the Do Not Call Registry?",options:["Once a year","Every 31 days","Every 90 days","Only when starting cold calling"],correctIndex:1,explanation:"Agents must check the Do Not Call Registry at least once every 31 days and remove any registered numbers from their calling lists. Available at www.donotcall.gov."},{id:"q141",category:"Do Not Call",question:"What is an Established Business Relationship (EBR) for Do Not Call purposes?",options:["Any previous contact","Transaction or inquiry within past 18 months","Permanent exemption once established","Only applies to current clients"],correctIndex:1,explanation:"EBR is a transaction or inquiry within the past 18 months that allows calling DNC registrants. Expires 18 months after last transaction or 3 months after inquiry."},{id:"q142",category:"Do Not Call",question:"Can you call an expired listing owner who is on the Do Not Call Registry?",options:["Yes, expired listings are always exempt","No, unless you have EBR or written consent","Yes, they are a lead","Yes, but only once"],correctIndex:1,explanation:"NO - unless you have an established business relationship (were their listing agent within 18 months) or they gave written consent. Another agent's expired listing does NOT give you exemption."},{id:"q143",category:"TCPA",question:"What does TCPA stand for?",options:["Telephone Consumer Protection Act","Telemarketing Consumer Privacy Agreement","Technology Communication Protection Act","Text Call Privacy Agreement"],correctIndex:0,explanation:"TCPA stands for Telephone Consumer Protection Act - federal law restricting telemarketing calls, auto-dialers, prerecorded messages, and texts. Requires prior express written consent for marketing to cell phones."},{id:"q144",category:"TCPA",question:"Can agents send marketing text messages without consent?",options:["Yes, texts are not regulated","Yes, to anyone you have business cards from","No, requires prior express written consent","Only to clients"],correctIndex:2,explanation:"NO - TCPA requires prior express written consent before sending marketing texts to cell phones. Violations carry penalties of $500-1,500 per text. Must keep records of consent."},{id:"q145",category:"TCPA",question:"What is the penalty for violating TCPA rules per call or text?",options:["$50-100","$500-1,500","$5,000-10,000","Just a warning"],correctIndex:1,explanation:"TCPA violations carry penalties of $500-1,500 per illegal call or text message. These can add up quickly if multiple violations occur, making compliance essential."},{id:"q146",category:"Do Not Call",question:"Which is exempt from Do Not Call rules?",options:["Real estate cold calling","Charitable organizations","All businesses","Anyone with a license"],correctIndex:1,explanation:"Exempt from DNC: charitable organizations, certain non-profits, political contribution solicitations, and surveys (without sales pitch). Real estate agents are NOT exempt."},{id:"q147",category:"Do Not Call",question:"What is the maximum penalty per illegal Do Not Call violation?",options:["$500","$5,000","$43,280 (adjusted for inflation)","$100,000"],correctIndex:2,explanation:"Do Not Call violations can result in penalties up to $43,280 per illegal call (adjusted for inflation). This makes compliance critical for real estate professionals."},{id:"q148",category:"Electronic Signatures",question:"What must happen before parties use electronic signatures?",options:["Nothing special required","All parties must consent to conduct business electronically","Attorney must approve","Notary must witness"],correctIndex:1,explanation:"All parties must consent to conduct business electronically before using e-signatures. Best practice: get written acknowledgment of consent. Parties can revoke consent and request paper documents."},{id:"q149",category:"Electronic Signatures",question:"What is e-filing in real estate?",options:["Email filing with broker","Electronic filing of documents with registry of deeds","Online listing submission","Digital photo storage"],correctIndex:1,explanation:"E-filing is electronic filing of documents with the registry of deeds or county recorder. Conveyancing attorneys can now file electronically without recording original paper documents in person."},{id:"q150",category:"TCPA",question:"What is an auto-dialer under TCPA?",options:["Speed dial function","Automatic telephone dialing system that dials from a list","Caller ID system","Voice mail"],correctIndex:1,explanation:"An auto-dialer is an automatic telephone dialing system that dials numbers from a list. TCPA heavily restricts auto-dialer use - requires prior express written consent to call cell phones with auto-dialers."},{id:"q151",category:"Do Not Call",question:'Can you call DNC registrants if you\'re offering a "free home valuation"?',options:["Yes, free offers are exempt from DNC","Yes, if it's truly free with no obligation",'No, offering "free" services does not exempt you from DNC rules',"Only if they requested it"],correctIndex:2,explanation:'NO - offering something "free" or "of value" does NOT exempt you from DNC rules. It\'s still telemarketing/solicitation promoting your business. You still need EBR or written consent. This is a common misconception.'},{id:"q152",category:"Do Not Call",question:'An agent wants to call offering "free market reports" to get around DNC rules. Is this allowed?',options:["Yes, educational information is exempt","Yes, as long as it's actually free","No, it's still telemarketing and requires EBR or consent","Yes, but only once per household"],correctIndex:2,explanation:'NO - this is a common violation attempt. Offering "free" market reports to promote your services is still telemarketing. You cannot use "free offers" to circumvent DNC rules. Requires EBR or consent.'},{id:"q153",category:"Do Not Call",question:'What determines if a call is "telemarketing" under DNC rules?',options:["Only calls asking for money","Any call promoting goods or services, even if free","Only calls selling products","Calls over 5 minutes"],correctIndex:1,explanation:"Telemarketing is ANY call to promote goods or services, even if free. Includes: free valuations, market reports, seminars, open houses (if promoting services). Purpose/intent matters, not cost."},{id:"q154",category:"Do Not Call",question:'What is the "intent test" for DNC telemarketing?',options:["What you say on the call","Whether you charge for services","If the purpose is to promote your business or generate future paid business","How long the call lasts"],correctIndex:2,explanation:'Courts look at PURPOSE/INTENT of the call. If intent is to promote your business or generate future paid business (even if offering something "free"), it\'s telemarketing. Cannot circumvent with "free offers."'},{id:"q155",category:"Do Not Call",question:"Which would still be considered telemarketing under DNC rules?",options:["Calling about a scheduled appointment","Returning a call the client made to you","Offering free CMAs to generate listing business","Transaction updates to current clients"],correctIndex:2,explanation:"Offering free CMAs to generate listing business IS telemarketing - you're promoting your services. Options A, B, D are generally not telemarketing (existing relationship, client-initiated, transaction-specific)."},{id:"q156",category:"TCPA",question:"What are the time restrictions for telemarketing calls under TCPA?",options:["Anytime is okay","8am-9pm local time of the person being called","9am-5pm business hours","8am-8pm your local time"],correctIndex:1,explanation:"TCPA prohibits telemarketing calls before 8am or after 9pm LOCAL TIME of the person being called. Must respect recipient's time zone, not your own. Violations subject to penalties."},{id:"q157",category:"TCPA",question:"What caller information must be disclosed under TCPA?",options:["Just your name","Name, phone number, and address where you can be reached","Only company name","No disclosure required"],correctIndex:1,explanation:"Must provide: (1) name of caller or entity, (2) telephone number and address where person/entity can be reached. Required at beginning of call. Failure to properly disclose violates TCPA."},{id:"q158",category:"TCPA",question:"Do ringless voicemails require consent under TCPA?",options:["No, they don't ring so they're exempt","Yes, require prior express written consent","Only if over 30 seconds","Only for marketing"],correctIndex:1,explanation:"YES - ringless voicemails require prior express written consent, same as auto-dialers and prerecorded messages. Technology that drops voicemail without ringing is still regulated. Cannot circumvent TCPA."},{id:"q159",category:"Do Not Call",question:"What is an internal DNC list?",options:["Same as National DNC","Company-specific list of people who asked not to be called by your company","Not required","Optional tracking"],correctIndex:1,explanation:"Internal DNC list is company-specific list of opt-out requests. TCPA requires maintaining it IN ADDITION to checking National DNC. Must honor immediately and keep for 5 years."},{id:"q160",category:"Do Not Call",question:"How long after an open house attendance can you call someone?",options:["Forever","3 months after the inquiry","18 months","1 week"],correctIndex:1,explanation:"Open house attendance creates an INQUIRY-based exception lasting 3 MONTHS. After 3 months, permission expires unless EBR established through transaction. Different from 18-month transaction EBR."},{id:"q161",category:"Do Not Call",question:"Can a buyer's agent call a FSBO seller on the DNC Registry to discuss their buyer client?",options:["No, FSBO are always off-limits","Yes, if contacting on behalf of agent's buyer client","Only with written permission","Never allowed"],correctIndex:1,explanation:"YES - buyer's agent can contact FSBO on behalf of buyer client. NO if seeking to solicit listing. Purpose matters: representing buyer = okay, soliciting listing = DNC violation without consent."},{id:"q162",category:"Do Not Call",question:"An agent closed a transaction on March 1, 2024. Until when can they call that client if on DNC?",options:["Forever, they're a past client","September 1, 2025 (18 months after)","June 1, 2024 (3 months)","1 year"],correctIndex:1,explanation:"TRANSACTION-based EBR lasts 18 MONTHS after end of transaction. March 1, 2024 + 18 months = September 1, 2025. After that, EBR expires and need written consent if on DNC."},{id:"q163",category:"Do Not Call",question:"What's the difference between the 3-month and 18-month EBR periods?",options:["No difference","3 months = inquiry, 18 months = completed transaction","3 months for buyers, 18 for sellers","3 months = first call, 18 = follow-ups"],correctIndex:1,explanation:"INQUIRY (open house, showing, website contact) = 3 months. TRANSACTION (completed purchase/sale as their agent) = 18 months. Transaction creates longer EBR than inquiry."},{id:"q164",category:"TCPA",question:"Which technologies require prior express written consent under TCPA?",options:["Only auto-dialers","Auto-dialers, prerecorded messages, and ringless voicemails","Just text messages","None if calling cell phones"],correctIndex:1,explanation:"ALL THREE require prior express written consent: auto-dialers, artificial voice/prerecorded messages, and ringless voicemails. Cannot use technology to circumvent consent requirements."},{id:"q165",category:"Do Not Call",question:"A commonly cited penalty for DNC violations is:",options:["$500 per call","$11,000 per call","$100 per call","Just a warning"],correctIndex:1,explanation:"Commonly cited as $11,000 per call (some sources cite up to $43,280 adjusted for inflation). FTC can impose civil penalties. Amount depends on circumstances and when violation occurred."},{id:"q166",category:"CAN-SPAM Act",question:"What does the CAN-SPAM Act regulate?",options:["Phone calls","Commercial email and junk email (spam)","Text messages only","Social media"],correctIndex:1,explanation:"CAN-SPAM Act is a federal law prohibiting deceptive email practices and junk email (spam). Requires truthful subject lines, unsubscribe options, physical address, and proper identification."},{id:"q167",category:"CAN-SPAM Act",question:"What MUST be included in all commercial marketing emails?",options:["Just your name","Unsubscribe mechanism, physical address, truthful subject lines","Only an email address","Nothing required"],correctIndex:1,explanation:"CAN-SPAM requires: (1) clear unsubscribe mechanism, (2) physical postal address, (3) truthful From/subject lines, (4) identify as advertisement if promotional. Must honor unsubscribe within 10 days."},{id:"q168",category:"CAN-SPAM Act",question:"How quickly must you process email unsubscribe requests?",options:["Immediately","Within 10 business days","Within 30 days","No requirement"],correctIndex:1,explanation:"Must honor unsubscribe requests within 10 BUSINESS DAYS. Cannot require login, payment, or more than email address to unsubscribe. Make it easy - single click or reply preferred."},{id:"q169",category:"CAN-SPAM Act",question:"What is the penalty for CAN-SPAM violations per email?",options:["$500","$5,000","$43,792 (adjusted for inflation)","$100"],correctIndex:2,explanation:"CAN-SPAM violations can result in penalties up to $43,792 per email (adjusted for inflation). Each separate email can be a separate violation. Criminal penalties possible for egregious cases."},{id:"q170",category:"COPPA",question:"What does COPPA stand for?",options:["Consumer Online Privacy Protection Act","Children's Online Privacy Protection Act","Commercial Online Privacy Act","California Privacy Protection Act"],correctIndex:1,explanation:"COPPA stands for Children's Online Privacy Protection Act - federal law protecting children under 13 online. Went into effect 7/1/13."},{id:"q171",category:"COPPA",question:"COPPA protects children under what age?",options:["Under 16","Under 13","Under 18","Under 21"],correctIndex:1,explanation:"COPPA protects children under 13 years old. Requires privacy policy and parental consent before collecting personal information from children younger than 13."},{id:"q172",category:"COPPA",question:"When did COPPA restrictions go into effect?",options:["January 1, 2000","July 1, 2013","January 1, 2020","July 1, 2010"],correctIndex:1,explanation:"July 1, 2013 (7/1/13) marked when most recent COPPA restrictions went into effect, including for mobile apps and networks. Requires posting privacy policy and limits data collection from children."},{id:"q173",category:"COPPA",question:"What does COPPA require before collecting data from children under 13?",options:["Nothing special","Verifiable parental consent","Just a privacy policy","Only applies to schools"],correctIndex:1,explanation:"COPPA requires verifiable parental consent before collecting personal information from children under 13. Must also have clear privacy policy and limit data collection."},{id:"q174",category:"Digital Compliance",question:"When is a privacy policy required for a real estate website?",options:["Never required","If collecting from children under 13 (COPPA) or in certain states","Only for large brokerages","Only if selling products"],correctIndex:1,explanation:"Privacy policy required by: COPPA (if collecting from children under 13), various state laws (CA, VA, CO), and best practice for all websites collecting personal data like email addresses and phone numbers."},{id:"q175",category:"CAN-SPAM Act",question:"Can you email past clients without getting consent first?",options:["No, never allowed","Yes, existing customer/client relationship (EBR) allows emails","Only with written permission","Only once per year"],correctIndex:1,explanation:"CAN-SPAM allows emailing existing customers/clients based on established business relationship (EBR). Must still provide unsubscribe option. Different from TCPA which requires consent for marketing texts."},{id:"q176",category:"Transaction Cycle",question:"How many days after offer acceptance is the P&S Agreement typically signed?",options:["3 days","10 days","30 days","Same day"],correctIndex:1,explanation:"P&S (Purchase & Sales Agreement) is typically executed within 10 DAYS from offer acceptance. This is when the transaction becomes more binding and deposit usually increases."},{id:"q177",category:"Transaction Cycle",question:"What is the typical home inspection/due diligence period?",options:["3 days","10 days from offer acceptance","30 days","60 days"],correctIndex:1,explanation:"Home inspection and due diligence period is typically 10 DAYS from offer acceptance. Buyer performs inspection, reviews condition, and can request repairs, negotiate, or cancel (with contingency)."},{id:"q178",category:"Transaction Cycle",question:"When does the lender's financing process typically begin?",options:["At offer acceptance","A couple days after signed P&S Agreement","30 days before closing","At closing"],correctIndex:1,explanation:"Financing process starts a couple days after the signed P&S Agreement. Lender then orders appraisal and title search, processes application, and works toward commitment letter."},{id:"q179",category:"Transaction Cycle",question:"What two items does the lender order at the start of financing?",options:["Survey and inspection","Appraisal and Title Search","Insurance and warranty","Credit report and tax returns"],correctIndex:1,explanation:"Lender orders: (1) Appraisal - property valuation by licensed appraiser, and (2) Title Search - examination of ownership history and liens. Both required for mortgage approval."},{id:"q180",category:"Transaction Cycle",question:"When is a mortgage commitment letter typically obtained?",options:["10 days from offer","30-45 days from P&S Agreement","At closing","7 days before closing"],correctIndex:1,explanation:"Commitment letter is typically obtained 30-45 DAYS from P&S Agreement. It's the lender's formal written promise to provide the mortgage loan, subject to clearing conditions."},{id:"q181",category:"Transaction Cycle",question:'What are "clear conditions" in a commitment letter?',options:["Inspection requirements","Requirements that must be satisfied before loan approval","Seller obligations","Closing costs"],correctIndex:1,explanation:"Clear conditions are requirements that must be satisfied before final loan approval. Examples: proof of insurance, income verification, credit explanations. Must be cleared PRIOR to closing AND at time of closing."},{id:"q182",category:"Transaction Cycle",question:'What does "Clear to Close" mean?',options:["Property passes inspection","Lender confirms all loan conditions met and loan is ready to fund","Seller can move out","Closing date is set"],correctIndex:1,explanation:"Clear to Close means lender approval confirming all loan conditions have been met and loan is ready to fund. Obtained shortly before closing (days before). Final step before closing day."},{id:"q183",category:"Transaction Cycle",question:"Which is a broker's responsibility in the transaction cycle?",options:["Approving the mortgage","Qualifying buyers and writing offers","Conducting the appraisal","Issuing title insurance"],correctIndex:1,explanation:"Broker responsibilities include: listing property, qualifying buyers, showing property, writing offers, coordinating inspections, executing P&S, and guiding parties through closing."},{id:"q184",category:"Transaction Cycle",question:"What is the correct sequence of major transaction milestones?",options:["Offer → Closing → P&S → Inspection","Offer → P&S (10 days) → Inspection (10 days) → Commitment (30-45 days from P&S) → Closing","Inspection → Offer → P&S → Closing","P&S → Offer → Commitment → Closing"],correctIndex:1,explanation:"Correct sequence: Offer → P&S within 10 days → Inspection within 10 days → Financing starts → Commitment letter 30-45 days from P&S → Clear conditions → Clear to Close → Closing."},{id:"q185",category:"Transaction Cycle",question:"Why is the P&S Agreement significant in Massachusetts?",options:["It's the first offer","Makes transaction more binding, increases deposit, sets closing date","It's when buyer gets keys","It replaces the offer"],correctIndex:1,explanation:"P&S makes transaction more binding (harder to cancel), increases deposit amount, sets closing date, and includes all final terms. Signed typically 10 days after offer acceptance."},{id:"q186",category:"WISP",question:"What does WISP stand for in Massachusetts?",options:["Written Insurance Security Protocol","Written Information Security Program","Wireless Internet Security Protection","Written Identity Safety Plan"],correctIndex:1,explanation:"WISP stands for Written Information Security Program - MA law requiring businesses to protect personal information collected from residents with a written security plan."},{id:"q187",category:"WISP",question:'What constitutes "personal information" under MA WISP?',options:["Just email addresses","Only Social Security Numbers","Name + SSN, Driver's License number, or financial account numbers","Public information from websites"],correctIndex:2,explanation:"Personal information = resident's name (first + last or first initial + last) PLUS any of: SSN, Driver's License/state ID number, financial account numbers, or credit/debit card numbers with access codes. Public information is excluded."},{id:"q188",category:"WISP",question:"What must be safeguarded under WISP?",options:["Only computer files","All paper, electronic records, computer systems, laptops & portable drives with personal info","Just client contracts","Only financial documents"],correctIndex:1,explanation:"WISP requires safeguarding ALL paper, electronic, and other records; computer systems; laptops; and portable drive devices that contain personal information. Comprehensive protection required."},{id:"q189",category:"WISP",question:"If you discover a data breach, who must you notify?",options:["Only your broker","Just the affected clients","MA Attorney General AND Director of Office of Consumer Affairs","No one if it's minor"],correctIndex:2,explanation:"MUST file notice with Massachusetts Attorney General AND Director of Office of Consumer Affairs. Also notify affected individuals. Required for anyone who knows of a breach in security laws."},{id:"q190",category:"WISP",question:"Which is a required component of WISP compliance?",options:["Website design","Written security plan with employee training and access controls","Social media policy only","Marketing materials"],correctIndex:1,explanation:"WISP requires written security plan, employee training, access controls, encryption, secure disposal, regular assessments, vendor management, and incident response plan."},{id:"q191",category:"Escrow Accounts",question:"When must earnest money be deposited into the broker's escrow account?",options:["Within 7 days","Immediately upon acceptance of Contract to Purchase","At closing","When P&S is signed"],correctIndex:1,explanation:"Earnest money MUST be deposited IMMEDIATELY upon acceptance of Contract to Purchase into broker's escrow account. Broker acts as Escrow Agent with fiduciary responsibilities."},{id:"q192",category:"Escrow Accounts",question:"What is the rule about commingling escrow funds?",options:["Can mix with operating funds temporarily","NO COMMINGLING - must be completely separate from operating account","Can combine if tracked separately","Allowed with written permission"],correctIndex:1,explanation:"NO COMMINGLING OF FUNDS - Cannot mix escrow money with operating account. Escrow account MUST be completely separate from broker's personal or business operating funds."},{id:"q193",category:"Escrow Accounts",question:"When can funds be released from an escrow account?",options:["Whenever broker decides","Only at consummation of sale, mutual consent/release, or court order","When buyer requests","After 30 days"],correctIndex:1,explanation:"Funds can ONLY be released at: (1) consummation of sale, (2) upon mutual consent/release, or (3) court ordered directive. Cannot release without proper authorization."},{id:"q194",category:"Record Keeping",question:"How long must copies of escrow account checks be kept?",options:["1 year","3 years","5 years","10 years"],correctIndex:1,explanation:"Copies of checks must be kept for 3 YEARS. Checkbook register must be kept for 10 YEARS. Records subject to inspection by the Board."},{id:"q195",category:"Record Keeping",question:"How long must the escrow account checkbook register be kept?",options:["3 years","5 years","10 years","Forever"],correctIndex:2,explanation:"Checkbook register must be kept for 10 YEARS. Copies of checks must be kept for 3 years. Records must show all deposits and withdrawals with complete details."},{id:"q196",category:"Escrow Accounts",question:"Who can have check signing authority on broker escrow accounts?",options:["Broker, salesperson, or bookkeeper","Only the broker","Anyone with authorization","Broker or accountant"],correctIndex:1,explanation:"Only a BROKER shall be permitted to have check signing authority. Bookkeepers, accountants, salespeople, or unlicensed assistants CANNOT have signing authority on escrow accounts."},{id:"q197",category:"Escrow Accounts",question:"What must escrow account records clearly indicate?",options:["Just the amounts","Date, from whom deposit given, date deposited, source, check number, withdrawals, recipients","Only deposits","Final balances only"],correctIndex:1,explanation:"Records must clearly show: date and from whom deposit given, date deposited, source of money, check number, date of withdrawal, name of persons receiving money, and any other pertinent info."},{id:"q198",category:"Escrow Accounts",question:"What is the VIP NOTE about contract binding and earnest money?",options:["Contract always binding when signed","Contract may not be binding until earnest money received by listing agent/brokerage","Earnest money not important","Can wait 30 days for deposit"],correctIndex:1,explanation:"VIP NOTE: Contract may not be binding until the earnest money is received by the listing agent/brokerage. Acceptance alone may not create binding contract - deposit receipt is critical."},{id:"q199",category:"Two-Contract System",question:"What are the two contracts used in Massachusetts real estate transactions?",options:["Offer and Closing","Offer to Purchase and Purchase & Sales Agreement (P&S)","Listing and Sale","Pre-approval and Final Contract"],correctIndex:1,explanation:"MA uses a two-contract system: (1) Offer to Purchase - initial agreement, and (2) Purchase & Sales Agreement (P&S) - comprehensive contract typically drafted by attorneys 10 days after offer acceptance."},{id:"q200",category:"Attorney Role",question:'What is the proper response when a client asks "Do I need an attorney?"',options:['"No, I can handle everything"','"You have the right to consult with an attorney. Many people choose to have an attorney review contracts and represent them at closing."','"Only if there are problems"','"Attorneys are too expensive"'],correctIndex:1,explanation:'Proper response acknowledges their right to an attorney, explains common practice, and recommends consideration without pressuring. NEVER say "You don\'t need an attorney" or discourage attorney involvement.'},{id:"q201",category:"Unauthorized Practice of Law",question:"Which action would be unauthorized practice of law for an agent?",options:["Explaining terms in a standard form","Interpreting legal consequences of a contract clause","Recommending they consult an attorney","Facilitating the transaction"],correctIndex:1,explanation:"Agents CANNOT interpret legal documents or explain legal consequences - that's practicing law. Agents CAN explain standard form terms, recommend consulting attorney, and facilitate the transaction."},{id:"q202",category:"Attorney Role",question:"When are attorneys typically brought into MA transactions?",options:["Only if problems arise","To draft and review the P&S Agreement after offer acceptance","Only at closing","Never needed"],correctIndex:1,explanation:"In MA, attorneys are typically involved to draft and review the P&S Agreement after offer acceptance, handle title work, and conduct closing. Most MA transactions involve attorneys for both parties."},{id:"q203",category:"Two-Contract System",question:"Why does Massachusetts use a two-contract system?",options:["To make process more complicated","To allow time for inspections and attorney review before final binding contract","Required by federal law","To increase agent commissions"],correctIndex:1,explanation:"Two-contract system allows: Offer to Purchase establishes basic agreement quickly, then P&S Agreement provides comprehensive legal terms after due diligence period with attorney involvement and full protections."},{id:"q204",category:"Attorney Role",question:"Which phrase should agents AVOID saying?",options:['"You should consult your attorney"','"This means you don\'t have to..."','"An attorney can explain this"','"Consider having an attorney review"'],correctIndex:1,explanation:'AVOID interpreting or explaining legal meaning ("This means..."). INSTEAD redirect to attorney consultation. Never say "You don\'t need an attorney", "The law requires...", or interpret legal consequences.'},{id:"q205",category:"Attorney Role",question:"Can agents recommend attorneys to clients?",options:["No, never allowed","Yes, can provide 2-3 names but no referral fees or pressure","Only if agent has business relationship","Yes, but must use agent's attorney"],correctIndex:1,explanation:"Agents CAN provide attorney names (typically 2-3 recommendations) but CANNOT receive referral fees, pressure clients, or fail to disclose business relationships. Must be neutral recommendations."},{id:"q206",category:"Attorney Role",question:"What do attorneys handle in MA real estate transactions?",options:["Only signing documents","Draft/review P&S, title search, resolve issues, conduct closing, prepare deed","Just the closing","Nothing - agents handle everything"],correctIndex:1,explanation:"MA attorneys: draft/review P&S Agreement, conduct title search, resolve title issues, review all documents, explain legal implications, handle closing, prepare deed, record documents, disburse funds."},{id:"q207",category:"Taxes",question:"What is the tax status of most real estate agents?",options:["Employees (W-2)","Independent Contractors (1099-NEC)","Partners","Volunteers"],correctIndex:1,explanation:"Most agents are Independent Contractors receiving 1099-NEC, not W-2 employees. Responsible for own taxes including self-employment tax (15.3%). Must pay quarterly estimated taxes."},{id:"q208",category:"Taxes",question:"What is the self-employment tax rate for independent contractors?",options:["7.65%","15.3%","10%","25%"],correctIndex:1,explanation:"Self-employment tax is 15.3% (Social Security 12.4% + Medicare 2.9%). Independent contractors pay both employee and employer portions. This is in addition to regular income tax."},{id:"q209",category:"Tax Deductions",question:"Which is a deductible expense for real estate agents?",options:["Personal groceries","Commute to regular office","E&O insurance and MLS dues","Personal vacation"],correctIndex:2,explanation:"E&O insurance, MLS dues, CE courses, marketing, home office, mileage (business), and professional services are deductible. Personal expenses and regular commute are NOT deductible."},{id:"q210",category:"Taxes",question:"When are quarterly estimated tax payments due?",options:["Every 3 months on the 1st","April 15, June 15, September 15, and January 15","Only at year-end","Monthly"],correctIndex:1,explanation:"Quarterly estimated taxes due: April 15, June 15, September 15, and January 15 of following year. Must pay if expecting to owe $1,000+. Use Form 1040-ES."},{id:"q211",category:"Tax Deductions",question:"What must you maintain to deduct vehicle mileage?",options:["Nothing required","Detailed mileage log with dates, destinations, business purpose","Just fuel receipts","Car registration only"],correctIndex:1,explanation:"Must keep detailed mileage log documenting: date, destination, purpose, miles. Can use standard mileage rate (~65-67 cents/mile) or actual expenses. Commute to regular office NOT deductible."},{id:"q212",category:"Tax Deductions",question:"What are the requirements for home office deduction?",options:["Any space used occasionally","Regular and exclusive use for business, principal place of business","Just having a desk at home","No requirements"],correctIndex:1,explanation:"Home office must be: (1) Regular and exclusive use for business, (2) Principal place of business. Can deduct based on square footage. Simplified method: $5/sq ft up to 300 sq ft."},{id:"q213",category:"Taxes",question:"What form do agents receive from brokers showing annual commissions?",options:["W-2","1099-NEC (Nonemployee Compensation)","W-4","1040"],correctIndex:1,explanation:"1099-NEC shows total commissions paid. Broker issues by January 31. Agents report on Schedule C (business income/expenses). NOT W-2 because agents are independent contractors, not employees."},{id:"q214",category:"Tax Recordkeeping",question:"How long should agents keep tax records?",options:["1 year","Minimum 3 years, but 7 years recommended","Forever","No need to keep records"],correctIndex:1,explanation:"Minimum 3 years (IRS audit period), but 7 years recommended. Keep receipts, mileage logs, bank statements, commission statements, 1099s, expense records. Digital copies acceptable."},{id:"q215",category:"Agency Law",question:"What are the 3 types of law governing real estate transactions?",options:["Federal, State, Local","Common Law, Statutory Law, Administrative Law","Civil, Criminal, Contract","Public, Private, Corporate"],correctIndex:1,explanation:"(1) Common Law - tradition/court decisions (Tristam's Landing), (2) Statutory Law - enacted by legislature (10-day lead paint), (3) Administrative Law - R.E. Commission rules (3 years + 25 hrs/week for broker)."},{id:"q216",category:"Agency Law",question:'What does "Caveat Emptor" mean and when was it the norm?',options:['"Buyer beware" - 1950s norm, brokers represented sellers only','"Seller beware" - 1990s','"Agent beware" - 2000s','"Broker beware" - 1980s'],correctIndex:0,explanation:"Caveat Emptor = \"let the buyer beware\". In the 1950s, brokers represented SELLER'S interests only. Buyers were on their own and often didn't realize brokers didn't represent them."},{id:"q217",category:"Agency Law",question:"What happened in the 1960s with broker cooperation?",options:["Brokers stopped working together","Brokers started sharing property info, created MLS, but both brokers still represented seller","Buyer agency was established","Nothing changed"],correctIndex:1,explanation:"In 1960s, brokers started sharing property information, formalizing cooperation through MLS creation. However, even when each party had a broker, BOTH brokers still represented the seller's interest."},{id:"q218",category:"Agency Law",question:"Tristam's Landing Rule is an example of which type of law?",options:["Statutory Law","Administrative Law","Common Law","Federal Law"],correctIndex:2,explanation:"Tristam's Landing Rule is Common Law - established by court decision and tradition, not enacted by legislature or created by administrative agencies."},{id:"q219",category:"Agency Law",question:"The 10-day lead paint inspection right is an example of which type of law?",options:["Common Law","Statutory Law","Administrative Law","Case Law"],correctIndex:1,explanation:"Statutory Law - enacted by legislation. Buyers have 10-day right to conduct lead paint risk assessment or inspection for properties built before 1978."},{id:"q220",category:"Agency Law",question:"The requirement to be a salesperson for 3 years working 25 hrs/week before becoming a broker is which type of law?",options:["Common Law","Statutory Law","Administrative Law","Constitutional Law"],correctIndex:2,explanation:"Administrative Law - rules and regulations authorized by Real Estate Commissions as approved by legislature. R.E. Commission sets licensing requirements like 3 years + 25 hrs/week."},{id:"q221",category:"Agency Law",question:"What was the historical problem with broker cooperation in the 1960s-1980s?",options:["Brokers wouldn't work together","Both brokers still represented seller even when each party had a broker","No one represented sellers","Buyers had too much representation"],correctIndex:1,explanation:"Even when seller and buyer each used a broker, BOTH brokers still represented the seller's interest. Buyers didn't have true representation - created conflicts until buyer agency was established."},{id:"q222",category:"Agency Law",question:"How did MLS creation affect agency representation?",options:["Created buyer agency","Formalized broker cooperation and info exchange but maintained seller-only representation","Eliminated all agency relationships","Required dual agency"],correctIndex:1,explanation:"MLS formalized broker cooperation and allowed property information sharing. However, it maintained seller-only representation - cooperating brokers shared commission but both still represented seller, not buyer."},{id:"q223",category:"Agency History",question:"What happened in 1990 in Massachusetts regarding agency?",options:["Buyer agency was created","Board created 1st written agency form - all agents represented seller unless disclosed","Agency was eliminated","Dual agency became required"],correctIndex:1,explanation:'1990: Board of Registration created 1st written agency form. All real estate agents represented the SELLER unless otherwise disclosed. Outside agents were called "Sub-Agents."'},{id:"q224",category:"Agency History",question:"What was the status of buyer agents in 1993?",options:["Fully recognized and well-compensated","Recognized but considered outcasts, offered zero compensation, had to get paid by buyer","Not allowed","Required for all transactions"],correctIndex:1,explanation:"1993: Buyer Agency was recognized but BUYER AGENTS were considered OUTCASTS. Agents would offer ZERO compensation, forcing Buyer Agents to get paid through Buyer directly."},{id:"q225",category:"Agency History",question:"What major change occurred in 2005 regarding agency?",options:["Agency was eliminated","VICARIOUS LIABILITY - must disclose relationship at first personal meeting, buyer agency widely recognized, sub-agency dead","Sub-agency became mandatory","Buyer agency was banned"],correctIndex:1,explanation:"2005: VICARIOUS LIABILITY rules - must disclose type of relationship and business model at first personal meeting. Introduced Facilitators and Designated Agency. BUYER AGENCY IS WIDELY RECOGNIZED AND SUB-AGENCY IS DEAD."},{id:"q226",category:"Agency History",question:"When must agency disclosure be given to prospective buyers/sellers?",options:["At closing","At the first personal meeting to discuss a specific property","Within 30 days","Only if they ask"],correctIndex:1,explanation:'Since 2005: Form MUST be given "at the first personal meeting to discuss a specific property." Must disclose type of relationship and type of business model.'},{id:"q227",category:"Agency History",question:"What is the Open House Exemption?",options:["No disclosure ever needed at open houses","Can post or provide written materials explaining agent relationship instead of formal disclosure","Must give disclosure to every visitor","Open houses are banned"],correctIndex:1,explanation:"Open House Exemption (2005): Can post or provide written materials explaining relationship of agent conducting the Open House. Don't need formal agency disclosure if written materials available."},{id:"q228",category:"Agency History",question:"When did buyer agency become widely recognized in MA?",options:["1990","1993","2005","2021"],correctIndex:2,explanation:"By 2005, BUYER AGENCY IS WIDELY RECOGNIZED AND SUB-AGENCY IS DEAD. Before 2005, buyer agents were outcasts. After 2005, buyer representation became standard with proper compensation."},{id:"q229",category:"Agency History",question:"What change was made to the agency disclosure form in 2021?",options:["Eliminated disclosure requirement","Revised form to include times when there is no personal meeting (Sight Unseen Buyers)","Made it longer and more complex","Required notarization"],correctIndex:1,explanation:"2021: Revised form to include times when there is no personal meeting (Sight Unseen Buyers - buying without in-person viewing). 2017 had made it easier to understand."},{id:"q230",category:"Agency History",question:'What are "Facilitators" and "Designated Agency"?',options:["Types of illegal agency","Terms from 2005 - Facilitators help but don't represent, Designated Agency assigns different agents in firm to each party","Old terms no longer used","Federal requirements"],correctIndex:1,explanation:"Announced in 2005: Facilitators help transaction but don't represent either party. Designated Agency: one agent in firm represents buyer, different agent represents seller, avoiding dual agency."},{id:"q231",category:"Negotiation",question:"Best response when seller asks you to lower commission rate?",options:["Immediately agree to lower rate","Focus on VALUE - show marketing plan, track record, and ROI of higher sale price","Apologize for high rate","Say all agents charge the same"],correctIndex:1,explanation:'Focus on VALUE not price. Show marketing plan and track record. Demonstrate ROI - a higher sale price justifies commission. Ask: "What\'s most important - highest price or saving on commission?"'},{id:"q232",category:"Negotiation",question:"What should you negotiate when joining a brokerage?",options:["Only commission split","Commission split, desk fees, cap, marketing support, training, technology, leads","Nothing - accept what's offered","Just the office location"],correctIndex:1,explanation:"Negotiate: Commission split, desk fees/monthly costs, cap, marketing budget, training, technology/CRM, lead generation, team vs solo, office access, admin support, E&O insurance, contract review period."},{id:"q233",category:"Negotiation",question:"How do you justify your commission rate?",options:["Say it's standard","Emphasize professional photography, marketing, expertise, time investment, and transaction coordination","Compare to other agents","Apologize but say you need it"],correctIndex:1,explanation:"Justify with: Professional photography, staging advice, MLS/social media marketing, open houses, negotiation expertise, market analysis, transaction coordination, network, time (15-25 hrs), insurance/licensing costs."},{id:"q234",category:"Negotiation",question:"What is a typical commission split for experienced agents?",options:["50/50","70/30 to 80/20","30/70","100/0"],correctIndex:1,explanation:"New agents: 50/50 to 60/40. Experienced: 70/30 to 80/20. Top producers: 85/15 to 95/5 or capped (100% after $16k-25k to broker). Varies by brokerage model."},{id:"q235",category:"Negotiation",question:"Key components of buyer broker agreement negotiation?",options:["Just duration","Value explanation, duration (3-6 months), compensation, termination clause","Only compensation","No negotiation needed"],correctIndex:1,explanation:"Explain value (exclusive rep, search, showings, negotiation, inspection, closing). Duration: 3-6 months. Compensation: buyer fee or seller-paid. Include termination clause. Flexible on exclusivity based on commitment."},{id:"q236",category:"Negotiation",question:"What should you NEVER do when negotiating commission?",options:["Show your marketing plan","Immediately discount, apologize for rate, or compete solely on price","Explain your services","Ask about their needs"],correctIndex:1,explanation:"NEVER: Immediately discount, apologize for rate, compete only on price, bad-mouth others, work free, compromise services for lower rate, negotiate against yourself, accept unprofitable terms, violate antitrust."},{id:"q237",category:"Negotiation",question:"What is a value proposition in real estate?",options:["Lowest commission rate","Clear statement of unique benefits: expertise, results, services, support that justify commission","List of all services","Comparison to other agents"],correctIndex:1,explanation:"Value proposition: clear statement of unique benefits justifying commission. Components: Expertise (certifications, experience), Results (sale price, days on market), Services (marketing, staging, photos), Support (availability, communication)."},{id:"q238",category:"Negotiation",question:'How to handle "I found an agent who will work for less"?',options:["Match their price immediately","Focus on delivering maximum value - 1% higher sale price covers commission difference","Bad-mouth the other agent","Give up"],correctIndex:1,explanation:'Response: "I understand you\'ve received other quotes. My focus is maximum value - highest price in shortest time. A 1% higher sale price covers the commission difference. See my marketing strategy and results?" Compete on results, not price alone.'},{id:"q239",category:"Tax Advice",question:'Client asks "Will I owe capital gains taxes on this sale?" Best response?',options:["Calculate their estimated tax",'"That requires professional advice from a CPA who can analyze your specific situation"',"Explain the tax rates","Tell them about the $250k/$500k exclusion"],correctIndex:1,explanation:'Proper response: "That\'s an important tax question requiring professional advice from a CPA or tax advisor. Implications vary based on YOUR situation - ownership, use, income, other factors. I can recommend a qualified tax professional." NEVER calculate taxes yourself.'},{id:"q240",category:"Tax Advice",question:"What constitutes unauthorized practice of accounting for real estate agents?",options:["Suggesting they talk to a CPA","Calculating capital gains, explaining tax implications, or recommending specific tax strategies","Providing CPA referrals","Mentioning tax professionals exist"],correctIndex:1,explanation:"Agents CANNOT: Calculate capital gains, explain tax implications, recommend tax strategies, complete tax forms, advise on 1031 exchanges, explain exclusion details, tell how to avoid taxes. CAN: Refer to CPA/EA, suggest tax discussion."},{id:"q241",category:"Tax Advice",question:"How should you discuss 1031 exchanges with clients?",options:["Explain all the rules and timelines",'"I\'ve heard of 1031 exchanges that may defer taxes, but rules are complex - speak with a CPA who specializes in this"',"Tell them it definitely applies","Calculate their potential savings"],correctIndex:1,explanation:"Proper: \"I've heard of something called a 1031 exchange that may allow tax deferral on investment properties. However, rules are very complex and specific. Speak with a CPA or tax attorney who specializes in 1031 exchanges.\" Don't explain rules yourself."},{id:"q242",category:"Tax Advice",question:"Client asks about primary residence capital gains exclusion. What do you say?",options:['"You get $250k if single, $500k if married"','"For primary residences, there may be tax benefits available, but qualifying rules are complex - consult a CPA"','"You lived here 2 years so you qualify"',"Calculate their exact exclusion amount"],correctIndex:1,explanation:'Proper: "For primary residences, there may be tax benefits available, but rules about qualifying are complex. A CPA can tell you if you meet requirements and how much benefit you might receive. Consult a tax professional before making decisions." Don\'t explain rules yourself.'},{id:"q243",category:"Tax Advice",question:"Why is it critical that agents NOT give tax advice?",options:["It takes too much time","Unauthorized practice of accounting, license risk, liability if wrong, clients can sue for damages","CPAs get jealous","It's not important"],correctIndex:1,explanation:"Critical reasons: (1) Unauthorized practice of accounting, (2) License suspension/revocation risk, (3) Liability if advice wrong, (4) Client can sue for damages, (5) Tax laws change frequently, (6) Individual situations vary, (7) Insurance may not cover, (8) Outside agent expertise."},{id:"q244",category:"Tax Advice",question:"Which phrase should agents AVOID saying?",options:['"You should consult a tax professional"','"You won\'t owe taxes because..." or "Your capital gains will be..."','"Tax implications may exist"','"A CPA can help with this"'],correctIndex:1,explanation:'AVOID: "You won\'t owe taxes because...", "Your capital gains will be...", "You can avoid taxes by...", "This qualifies for 1031", "You meet the 2/5 years", "Your exclusion is $250k/$500k". These constitute tax advice and create liability.'},{id:"q245",category:"Tax Advice",question:"How do you properly recommend a tax professional?",options:["Tell them which one to use",'"I can provide names of 2-3 CPAs/EAs who specialize in real estate taxation - would you like referrals?"',"Receive commission for referral","Only recommend one person"],correctIndex:1,explanation:'Proper: "I can provide names of 2-3 CPAs or Enrolled Agents who specialize in real estate taxation. They can analyze your complete situation and provide personalized advice. Would you like those referrals?" Cannot receive kickbacks. Must disclose business relationships.'},{id:"q246",category:"Tax Advice",question:'Client says "My friend told me I don\'t owe any taxes." Best response?',options:["\"That's right, you won't\"",'"Everyone\'s tax situation is unique - what applies to your friend may not apply to you. Consult YOUR CPA"','"Your friend is wrong"',"Explain why their friend was mistaken"],correctIndex:1,explanation:'Response: "Everyone\'s tax situation is unique. What applies to your friend may not apply to you. I strongly recommend consulting with your CPA or tax advisor to understand YOUR specific situation. Tax laws are complex and penalties significant. A tax professional gives accurate guidance for YOUR circumstances."'},{id:"q247",category:"Open House",question:"What are the agency disclosure requirements for open houses in MA?",options:["Must give disclosure to every visitor","Can post written materials explaining agent relationship instead of formal one-on-one disclosure","No disclosure needed at open houses","Only disclose to serious buyers"],correctIndex:1,explanation:"Open House Exemption (2005): Can post or provide written materials explaining relationship of agent conducting open house. Don't need formal one-on-one disclosure IF written materials clearly posted/available. Must still disclose if discussing specific offers/representation."},{id:"q248",category:"Open House",question:"What should sellers NEVER say at open houses?",options:["Welcome, feel free to look around",'"We need to sell by [date]" or "We\'ve had no offers" or "We already dropped the price"',"My agent's card is on the table","Please sign in"],correctIndex:1,explanation:'NEVER say: "We need to sell by [date]", "We\'ve had no offers", "We already dropped the price", "We\'ll consider any offer", "We\'re desperate/divorced/relocating". These destroy negotiating position and give buyer agents ammunition for lowball offers.'},{id:"q249",category:"Open House",question:"Best advice to give sellers before an open house?",options:["Stay and answer all questions",'Leave the property - if you must stay, say only "My agent can answer that"',"Tell visitors everything about the house","Negotiate directly with buyers"],correctIndex:1,explanation:"Tell sellers: \"Please LEAVE during open house. If you stay, don't discuss timeline, motivation, price reductions, offers, or personal situation. Say only 'My agent can answer that.' Visitors may be buyer agents gathering intel to lowball you!\""},{id:"q250",category:"Open House",question:"What information damages seller's negotiating position?",options:["Property features and upgrades","Time pressure, motivation (divorce/job transfer), lack of offers, previous price drops","School district information","Square footage"],correctIndex:1,explanation:"Damaging info: Time pressure (must sell by date), motivation (divorce, job transfer, financial), lack of offers, previous price drops, days on market, previous deals falling through, seller desperation. Buyer agents use this to justify lowball offers."},{id:"q251",category:"Open House",question:"If a visitor asks seller questions at open house, best response?",options:["Answer everything honestly",'"My agent can answer that - here\'s their card"',"Make up answers","Ignore them"],correctIndex:1,explanation:'Safe responses: "My agent can answer that - here\'s their card", "That\'s a great question for my agent", "My agent has all that information", "My agent is handling all inquiries". Keep friendly but refer everything to agent. Better yet - LEAVE!'},{id:"q252",category:"Open House",question:"Why should sellers leave during open houses?",options:["To go shopping","Buyers uncomfortable, sellers reveal damaging info, removes pressure, professional presentation","Required by law","Agent wants the house empty"],correctIndex:1,explanation:"Reasons: (1) Buyers feel uncomfortable looking freely, (2) Sellers accidentally reveal damaging info, (3) Sellers get emotional/defensive, (4) Can't ask seller to leave when they're there, (5) Buyer agents pump sellers for info, (6) Removes awkwardness, (7) Professional. Best practice: ALWAYS leave."},{id:"q253",category:"Open House",question:"How do buyer agents extract damaging information at open houses?",options:["They don't","Ask innocent questions about timeline, motivation, offers; engage seller in conversation; look for clues","They demand answers","They threaten sellers"],correctIndex:1,explanation:"Tactics: Ask innocent-sounding questions to get timeline, motivation, financial pressure. Look for clues (moving boxes, transfer papers). Engage seller in conversation. Ask about offers, time on market, price changes. Use any admission of pressure to justify lowball offers. Information = power."},{id:"q254",category:"Open House",question:"Key open house best practices for listing agents?",options:["Let anyone wander freely","Post agency disclosure, sign-in sheet, business cards, keep seller away, follow up with attendees","No documentation needed","Only let in pre-approved buyers"],correctIndex:1,explanation:"Best practices: Post agency disclosure signs, sign-in sheet, take business cards, pre-qualify visitors if possible, don't discuss other offers, keep seller away, follow up with all attendees, note buyer agent attendance, document showing, maintain security, lock rooms if needed."},{id:"q255",category:"Fiduciary Duties",question:'What does "OLD CAR" stand for?',options:["Old Commercial And Residential","Obedience, Loyalty, Disclosure, Confidentiality, Accountability, Reasonable Care","Only Licensed Dealers Can Accept Requests","Offer, List, Deal, Close, Account, Report"],correctIndex:1,explanation:"OLD CAR = 6 fiduciary duties agents owe clients: (O)bedience - obey lawful directions, (L)oyalty - client interests above all, (D)isclosure - disclose material facts/defects, (C)onfidentiality - keep info private, (A)ccountability - protect money/documents, (R)easonable Care - use skills to protect clients."},{id:"q256",category:"Fiduciary Duties",question:"What is the fiduciary duty of OBEDIENCE?",options:["Always do what client says, even if illegal","Must obey all LAWFUL directions from client; refuse unlawful directions","Obey broker, not client","Follow MLS rules"],correctIndex:1,explanation:"Obedience: Must obey all LAWFUL directions from client. Follow client instructions unless illegal, unethical, or impossible. Cannot substitute own judgment. If client gives unlawful direction (discrimination, fraud), must refuse and can terminate. Client is boss within legal bounds."},{id:"q257",category:"Fiduciary Duties",question:"What is the fiduciary duty of LOYALTY?",options:["Loyal to broker only","Client interests above ALL others, including agent's own - no self-dealing, present all offers","Loyal to whichever side pays more","Loyal to MLS"],correctIndex:1,explanation:"Loyalty: Client's interests above ALL others - including agent's own. No self-dealing, no secret profits, no dual agency without consent, no steering, must present ALL offers, negotiate best for client. Agent works FOR client, not against or for own benefit."},{id:"q258",category:"Fiduciary Duties",question:"What is the fiduciary duty of DISCLOSURE?",options:["Disclose everything to everyone","Must disclose material facts/defects to CLIENT - property issues, better offers, conflicts of interest","Never disclose anything","Only disclose what's required by law"],correctIndex:1,explanation:'Disclosure: Must disclose any "material facts or defects" TO CLIENT. Includes: property defects known to agent, better offers, buyer financial weakness, seller motivation if known, conflicts of interest, market conditions, comparables. Duty to investigate and inform. Cannot hide info affecting client decisions.'},{id:"q259",category:"Fiduciary Duties",question:"What is the fiduciary duty of CONFIDENTIALITY?",options:["Tell everyone everything",'"Lips sealed" - keep client info private (bottom line, max price, motivation); exceptions: court order, consent',"Only keep info private for 30 days","Confidentiality doesn't apply to agents"],correctIndex:1,explanation:'Confidentiality: "Lips sealed" - keep client info private. Cannot disclose: seller bottom line, buyer max price, motivation/desperation, personal/financial info, negotiating position. Extends beyond transaction. Exceptions: court order, client consent, legal requirement (fraud/crime).'},{id:"q260",category:"Fiduciary Duties",question:"What is the fiduciary duty of ACCOUNTABILITY?",options:["Keep receipts for yourself","Account for & protect earnest money/documents - prompt deposit, accurate records, never commingle","Count all showings","Report to broker only"],correctIndex:1,explanation:"Accountability: Duty to account for & protect earnest money and legal documents. Must: deposit funds promptly in escrow, maintain accurate records, provide accounting when requested, protect client assets, never commingle funds, safeguard documents, track all money, return unused funds."},{id:"q261",category:"Fiduciary Duties",question:"What is the fiduciary duty of REASONABLE CARE?",options:["Do minimum required","Utilize skills/expertise to protect clients - competent service, investigate, verify info, meet deadlines","Just show properties","Care only about commission"],correctIndex:1,explanation:"Reasonable Care: Utilize skills and expertise to protect clients. Must: provide competent service, investigate property, verify information, give accurate advice, meet deadlines, communicate promptly, know market, understand contracts, recommend professionals, disclose when beyond expertise. Professional standard required."},{id:"q262",category:"Fiduciary Duties",question:"To whom do agents owe fiduciary duties?",options:["Everyone in the transaction","ONLY to their clients (principals) under written agency agreement - not to customers","Only to the broker","To both buyer and seller equally"],correctIndex:1,explanation:"Agents owe fiduciary duties ONLY to their clients (principals) - the party they represent under written agency agreement. Seller agents owe to seller. Buyer agents owe to buyer. Do NOT owe fiduciary duties to customers (other party), though must be honest/fair. Fiduciary = special trust with CLIENT only."},{id:"q263",category:"Ethics",question:'What is the difference between "Realtor®" and "real estate agent"?',options:["No difference - same thing","Realtor® = NAR member pledged to Code of Ethics; real estate agent = licensed but may not be NAR member","Realtor® is higher license level","Only commercial agents are Realtors®"],correctIndex:1,explanation:"Realtor® = trademarked term for NAR (National Association of Realtors) members who pledge to follow Code of Ethics. Real estate agent = licensed but may not be NAR member. Only Realtors® can use term/logo. Realtors® have higher ethical standards, ethics education, can be disciplined by Professional Standards."},{id:"q264",category:"Ethics",question:"How do ethics differ from law in real estate?",options:["Ethics and law are the same","LAW = minimum legal baseline (state enforced); ETHICS = higher professional standards (NAR enforced)","Ethics don't matter if you follow the law","Law is optional, ethics are required"],correctIndex:1,explanation:"LAW = minimum legal requirements enforced by state (license law). ETHICS = higher professional standards enforced by associations (NAR Code). Can be legal but unethical. Ethics violations = fines, suspension from association. Law violations = license suspension/revocation, criminal/civil penalties. Ethics aspirational; law mandatory baseline."},{id:"q265",category:"Ethics",question:"What are the 3 major sections of the NAR Code of Ethics?",options:["Buying, Selling, Leasing","Articles 1-9 (clients/customers), 10-14 (public), 15-17 (Realtors®)","Residential, Commercial, Industrial","Federal, State, Local"],correctIndex:1,explanation:"Article 1-9: Duties to CLIENTS and customers (fiduciary duties, honesty, competence, disclosure). Article 10-14: Duties to the PUBLIC (fair housing, truthful advertising, no unauthorized practice of law). Article 15-17: Duties to REALTORS® (cooperation, arbitration, respect). Total: 17 Articles with Standards of Practice."},{id:"q266",category:"Ethics",question:"What is a Professional Standards proceeding?",options:["State license board hearing","NAR process for ethics complaints - Grievance Committee → Hearing Panel → Sanctions (fine up to $15k, suspension, expulsion)","Court trial","MLS rules enforcement"],correctIndex:1,explanation:"NAR process to handle ethics complaints between Realtors® or arbitration of commission disputes. Process: Complaint filed → Grievance Committee reviews → Hearing Panel decides → Sanctions if violated (warning, fine up to $15,000, suspension, expulsion). Separate from state license board. Can lose Realtor® status while keeping license."},{id:"q267",category:"Ethics",question:"What are common ethics violations in real estate?",options:["Being too nice to clients","Misrepresentation in marketing, failure to present all offers, undisclosed dual agency, discrimination","Working too many hours","Charging commission"],correctIndex:1,explanation:"Common violations: Misrepresentation/exaggeration in marketing, failure to present all offers, undisclosed dual agency, discrimination, unauthorized practice of law, disparaging competitors, failure to cooperate with other Realtors®, commission disputes, property condition misrepresentation, kickbacks without disclosure, failure to disclose interest."},{id:"q268",category:"Ethics",question:"What are consequences of ethics violations?",options:["Automatic license revocation","NAR sanctions: warning, fine ($0-$15k), probation, suspension, expulsion from association - separate from license","No consequences","Only a verbal warning"],correctIndex:1,explanation:"NAR Sanctions: Letter of warning, fine ($0-$15,000), education requirement, probation, suspension from association (1-3 years), expulsion (lose Realtor® status). Does NOT affect license (that's state board). Can also face: civil lawsuit, loss of commission, reputation damage, loss of MLS access. Ethics violation can LEAD to license complaint."},{id:"q269",category:"Ethics",question:"What is Article 1 of the Code of Ethics?",options:["Always get the highest commission","Protect and promote client interests (primary), but treat all parties honestly","Never work with buyers","Only show expensive properties"],correctIndex:1,explanation:'Article 1: "When representing a buyer, seller, landlord, tenant, or other client as an agent, Realtors® pledge themselves to protect and promote the interests of their client. This obligation to the client is primary, but it does not relieve Realtors® of their obligation to treat all parties honestly." Foundation of fiduciary duty and loyalty.'},{id:"q270",category:"Ethics",question:"How can ethics violations lead to legal liability?",options:["They can't - ethics and law are completely separate","Ethics violations that also violate law create liability: discrimination → lawsuit, misrepresentation → fraud, kickbacks → RESPA violation","Only NAR can punish you","Ethics violations don't matter"],correctIndex:1,explanation:"Ethics violations that also violate law create legal liability: Discrimination → Fair Housing lawsuit, Misrepresentation → fraud lawsuit, Undisclosed dual agency → license revocation + lawsuit, Unauthorized practice of law → license suspension + client damages, Kickbacks → RESPA violation (3x damages + attorney fees). Ethics complaint can trigger license investigation and civil lawsuit."},{id:"q271",category:"Fair Housing",question:"What are the 7 federal Fair Housing protected classes?",options:["Race, Color, Religion, Age, Sex, Disability, Income","Race, Color, Religion, National Origin, Sex, Familial Status, Disability","Race, Religion, Age, Marital Status, Sex, Disability, Ancestry","Race, Color, National Origin, Age, Gender Identity, Disability, Veteran Status"],correctIndex:1,explanation:"Federal protected classes (Title VIII Fair Housing Act 1968): (1) Race, (2) Color, (3) Religion, (4) National Origin, (5) Sex (includes sexual harassment), (6) Familial Status (children under 18, pregnant, custody), (7) Disability. Violations = HUD fines $16k-$65k, unlimited civil damages, criminal charges, license revocation."},{id:"q272",category:"Fair Housing",question:"What additional protected classes does MA provide beyond federal Fair Housing?",options:["None - MA follows federal only","Sexual Orientation, Gender Identity, Age, Marital Status, Military/Veteran, Ancestry, Public Assistance","Only Age and Sexual Orientation","Income and Education"],correctIndex:1,explanation:"MA Chapter 151B adds: Sexual Orientation, Gender Identity, Age, Marital Status, Military/Veteran Status, Ancestry, Public Assistance (Section 8). MA law is BROADER than federal. Always follow law that provides MORE protection. Agents must comply with both federal AND state law."},{id:"q273",category:"Fair Housing",question:'What is "steering" in Fair Housing context?',options:["Guiding clients through the buying process","Channeling buyers/renters to or away from neighborhoods based on protected class - ILLEGAL","Recommending certain properties","Showing properties in specific order"],correctIndex:1,explanation:'Steering: Channeling buyers/renters to or away from neighborhoods based on protected class. Examples: "You\'d be happier in this neighborhood" (race-based), "More people like you there", only showing certain areas to certain groups. ILLEGAL under Fair Housing. Violation = HUD fines, civil lawsuit, license suspension. Must show all properties equally.'},{id:"q274",category:"Fair Housing",question:"Which advertising phrase violates Fair Housing?",options:["Master bedroom, walk to schools, quiet neighborhood",'"No children", "Adults only" (except qualified senior), "Perfect for traditional family"',"Spacious, updated, modern, charming","Pet-friendly, near parks, convenient to shopping"],correctIndex:1,explanation:'Prohibited: "No children", "Adults only" (except qualified senior 55+/62+), "Perfect for traditional family", "Christian community", "No wheelchairs", "English-speaking only". Photos showing only one race also prohibited. SAFE: master bedroom, walk to schools, quiet neighborhood, spacious, pet-friendly. Must use diverse representation.'},{id:"q275",category:"Fair Housing",question:'Client says "I don\'t want to sell to [protected class]." Best response?',options:["Agree to accommodate their request",'"Fair Housing laws prohibit me from discriminating. I cannot honor that request and must withdraw if you insist"',"Just don't tell anyone","Ignore the comment"],correctIndex:1,explanation:'Response: "Federal and state Fair Housing laws prohibit me from discriminating based on [race, religion, etc.]. As licensed professional, I\'m required to treat all buyers equally. I cannot and will not honor that request. If you cannot comply with Fair Housing law, I must withdraw from representing you." Document refusal. Terminate if client insists.'},{id:"q276",category:"Fair Housing",question:"Difference between reasonable accommodations vs reasonable modifications?",options:["No difference - same thing","Accommodations = policy changes (service animals, parking); Modifications = physical changes at tenant expense (ramps, grab bars)","Accommodations are free, modifications cost money","Only accommodations are required by law"],correctIndex:1,explanation:'Reasonable Accommodations (policy changes): Service animals in "no pets" buildings, reserved parking, modified payments, communication accommodations. Reasonable Modifications (physical at tenant expense): Grab bars, ramps, widen doorways, lower countertops. Can ask for disability documentation. CANNOT ask "What\'s wrong?" or severity.'},{id:"q277",category:"Fair Housing",question:"What are Fair Housing violation penalties?",options:["Just a warning","HUD: $16k-$65k; Federal Lawsuit: UNLIMITED damages + criminal charges; State: license revocation; NAR: $15k + expulsion","Small fine only","No penalties if client requested it"],correctIndex:1,explanation:"HUD Administrative: $16k (1st), $37.5k (2nd in 5yr), $65k (3rd+ in 7yr) + fees + damages. Federal Lawsuit: UNLIMITED compensatory/punitive damages, attorney fees, criminal charges if willful (fines + prison). State: License suspension/revocation. NAR: Article 10 violation, $15k fine, expulsion. Career ending."},{id:"q278",category:"Fair Housing",question:"Do Fair Housing exemptions apply to real estate agents?",options:["Yes - we get all exemptions","NO - exemptions are narrow (religious orgs, private clubs, senior 55+/62+, owner-occupied 3 units) and DON'T APPLY to agents","Only religious exemption applies","We can decide which exemptions to use"],correctIndex:1,explanation:"NO! Exemptions very narrow: Religious organizations (non-commercial only), private clubs, senior housing 55+/62+, owner-occupied 3 units or fewer (but LOSES exemption if use broker/agent!). If you're involved as real estate professional, exemptions DON'T APPLY. Always assume Fair Housing applies. Fair Housing is NON-NEGOTIABLE."},{id:"q279",category:"Financing - ARMs",question:'In an Adjustable Rate Mortgage (ARM), what is the "index"?',options:["The profit margin charged by the lender","A financial indicator like SOFR or Treasury rates that the rate is tied to","The maximum rate cap over the life of the loan","The adjustment period between rate changes"],correctIndex:1,explanation:"The index is a financial indicator (SOFR, Treasury rates, Cost of Funds) that moves up/down with market conditions. The ARM rate = Index + Margin. The index is beyond borrower and lender control."},{id:"q280",category:"Financing - ARMs",question:"If an ARM has an index of 1.5% and a margin of 2%, what is the total interest rate?",options:["0.5%","1.5%","2%","3.5%"],correctIndex:3,explanation:"Interest rate = Index + Margin. 1.5% + 2% = 3.5%. The margin is fixed for the life of the loan, but the index changes with market conditions."},{id:"q281",category:"Financing - ARMs",question:'What is a "5/1 ARM"?',options:["Fixed for 5 months, then adjusts every 1 month","Fixed for 5 years, then adjusts every 1 year thereafter","Adjusts 5 times in the first year","Has a 5% rate with 1% margin"],correctIndex:1,explanation:"A 5/1 ARM is fixed for the first 5 years, then adjusts every 1 year after that. Common ARM types: 5/1, 7/1, 10/1, 3/1."},{id:"q282",category:"Financing - ARMs",question:'What is "negative amortization" in an ARM?',options:["Paying extra principal each month","When payment cap limits payment but rate increased, causing loan balance to grow","When the ARM rate decreases","Refinancing the loan"],correctIndex:1,explanation:"Negative amortization occurs when the payment cap limits your payment but the rate increased, so the shortfall is added to principal. You end up owing MORE than you borrowed!"},{id:"q283",category:"Financing - ARMs",question:"What is a typical periodic rate cap for ARMs?",options:["0.5% per adjustment","1% per adjustment","2% per adjustment","5% per adjustment"],correctIndex:2,explanation:"ARMs typically have a 2% periodic rate cap (maximum change per adjustment) and 6% lifetime cap over the life of the loan."},{id:"q284",category:"Financing - Amortization",question:"On a 30-year fixed mortgage, when do principal and interest payments reach 50/50?",options:["Year 5","Year 10","Year 15 (halfway)","Year 23-24"],correctIndex:3,explanation:"The 50/50 milestone occurs around years 23-24 on a 30-year mortgage. Early years are mostly interest (80% year 1), not principal. This is why extra payments early save so much money."},{id:"q285",category:"Financing - Amortization",question:"In Year 1 of a 30-year mortgage, approximately what percentage goes to interest?",options:["20%","50%","65%","80%"],correctIndex:3,explanation:"In Year 1, approximately 80% of your payment goes to interest and only 20% to principal. By Year 10, it's about 65% interest. This is why equity builds slowly at first."},{id:"q286",category:"Financing - Default",question:"What is the typical grace period for mortgage payments before late fees apply?",options:["5 days","10-15 days","30 days","60 days"],correctIndex:1,explanation:"Most mortgages have a 10-15 day grace period after the due date before late fees (typically 4-5% of payment) are charged. FHA loans have a 3-month grace period before foreclosure can begin."},{id:"q287",category:"Financing - Foreclosure",question:"What are the two types of foreclosure proceedings?",options:["Fast and slow","Judicial (court) and Statutory (power of sale)","Bank and government","Voluntary and involuntary"],correctIndex:1,explanation:"Judicial foreclosure requires court proceedings (6-18 months), while Statutory foreclosure uses power of sale clause (2-4 months, no court). Massachusetts primarily uses statutory foreclosure."},{id:"q288",category:"Financing - Foreclosure MA",question:"Does Massachusetts have a statutory right of redemption after foreclosure sale?",options:["Yes, 1 year after sale","Yes, 6 months after sale","No - right terminates at moment of foreclosure sale","Yes, 30 days after sale"],correctIndex:2,explanation:"CRITICAL MA RULE: Massachusetts has NO statutory right of redemption. The right terminates at the moment of foreclosure sale. This applies to foreclosure sales, Sheriff's Sales, and Tax Sales."},{id:"q289",category:"Financing - Foreclosure MA",question:"Who does the Soldiers and Sailors Civil Relief Act (SCRA) protect?",options:["All veterans","Active duty military and up to 3 months after leaving service","Only combat veterans","Military retirees only"],correctIndex:1,explanation:"SCRA bars lenders from foreclosing on active duty service members or until 3 months after leaving service. Court approval required, interest may be capped at 6% during active duty."},{id:"q290",category:"Financing - Short Sale",question:"What is a short sale?",options:["Selling a property quickly","Selling for less than owed with lender approval","A foreclosure auction","Selling without an agent"],correctIndex:1,explanation:"Short sale: Home worth less than mortgage owed, lender agrees to accept less than owed (takes a loss). Seller avoids foreclosure but gets no proceeds. Requires lender approval, takes 3-6 months typically."},{id:"q291",category:"Financing - Balloon Payment",question:"What is a balloon payment?",options:["Extra payment to reduce interest","Larger final payment that pays off the loan","Monthly escrow payment","Down payment at closing"],correctIndex:1,explanation:"Balloon payment: Larger final payment that pays off the loan. Example: 30-year amortization but loan due in 7 years. Normal monthly payments, then entire remaining balance due at year 7. Common in seller financing."},{id:"q292",category:"Financing - Clauses",question:"What is the Alienation Clause (due-on-sale clause)?",options:["Buyer can take over seller's loan","When property sold, lender calls note due in full","Seller must pay extra fees","Property cannot be sold for 5 years"],correctIndex:1,explanation:"Alienation Clause: When property is sold, lender will call note due in full. Prevents buyer from taking over old loan at more attractive terms. Standard in nearly all modern mortgages. Exception: FHA/VA loans often assumable."},{id:"q293",category:"Financing - Clauses",question:"What is the Assignment Clause in a mortgage?",options:["Borrower can assign mortgage to someone else","Lender can assign mortgage & note to secondary market (Fannie Mae/Freddie Mac)","Agent assigns commission to another agent","Property can be reassigned to new owner"],correctIndex:1,explanation:"Assignment Clause: Gives lender right to sell mortgage to secondary market (Fannie Mae/Freddie Mac) to free up cash. Borrower usually keeps paying same servicer. Most mortgages are sold after origination."},{id:"q294",category:"Financing - Clauses",question:"What is an Estoppel Clause (Certificate of No Defense)?",options:["Borrower can dispute loan terms anytime","Borrower cannot challenge terms if mortgage assigned to 3rd party","Lender must provide loan history","Property is free of liens"],correctIndex:1,explanation:'Estoppel Clause: Bars borrower from challenging mortgage terms if assigned to 3rd party. Also called "Certificate of No Defense." Protects new lender/investor. More common in commercial real estate.'},{id:"q295",category:"Financing - Clauses",question:"What is a Partial Release Clause used for?",options:["Releasing borrower from entire mortgage","Allowing partial release of property from blanket mortgage (subdivision development)","Reducing interest rate","Extending loan term"],correctIndex:1,explanation:"Partial Release Clause: Allows release of portion of security without releasing entire mortgage. Critical for subdivisions - developer can sell individual lots while keeping blanket mortgage. Payment usually required for each release."},{id:"q296",category:"Financing - Subordination",question:"When is a Subordination Agreement used?",options:["When refinancing but want to keep 2nd mortgage in 2nd position","When paying off all mortgages","When selling property","When making extra payments"],correctIndex:0,explanation:"Subordination Agreement: When refinancing, old 2nd lender agrees to stay in 2nd position behind new refinanced 1st mortgage. Both lenders must sign. Protects new lender's 1st position. Fee typically $200-$500."},{id:"q297",category:"Financing - Straight Loan",question:"What is a Straight Loan (interest-only loan)?",options:["Fixed rate for entire term","Interest-only payments, full principal due at end","No interest charged","Automatically renews"],correctIndex:1,explanation:"Straight Loan: Interest-only payments, full principal due at end. Example: $300K at 6%, pay $1,500/mo interest for 5 years, then $300K balloon. Lower payments but no equity building. Rare for residential."},{id:"q298",category:"Financing - CLUE Report",question:"What does a CLUE Report show?",options:["Credit score","Insurance claims on property in past 5 years","Property taxes owed","Mortgage payment history"],correctIndex:1,explanation:"CLUE (Comprehensive Loss Underwriting Exchange): Database of insurance claims on property in past 5 years. Shows claim type, amount, status. Frequent claims = red flags (property problems) or higher insurance rates/denial. Free once/year at PersonalReports.LexisNexis.com."},{id:"q299",category:"Financing - Forbearance",question:"What is mortgage forbearance?",options:["Forgiveness of debt","Temporary postponement of payments (not forgiveness)","Lower interest rate permanently","Extended loan term"],correctIndex:1,explanation:"Forbearance: POSTPONEMENT of obligations, NOT forgiveness. Lender allows reduced/no payments for 3-12 months, but all missed payments must be repaid later. Life of loan extended. Better than default but requires repayment plan."},{id:"q300",category:"Financing - Dodd-Frank",question:"When did the Dodd-Frank Act take effect?",options:["January 10, 2008","January 10, 2014","January 10, 2020","January 10, 2025"],correctIndex:1,explanation:"Dodd-Frank Act took effect January 10, 2014. Major federal consumer protection law regulating mortgage lenders and servicers. Requires 10 specific lender obligations."},{id:"q301",category:"Financing - Dodd-Frank",question:"Under Dodd-Frank, how much advance notice must lenders give for ARM rate changes?",options:["30 days","60-120 days (2 months)","1 year","No notice required"],correctIndex:1,explanation:"Dodd-Frank requires lenders give 60-120 days (2 months) warning before ARM rate changes. Notice must show current rate, new rate, and new payment amount. Helps borrower prepare."},{id:"q302",category:"Financing - Dodd-Frank",question:"Under Dodd-Frank, when can lenders start foreclosure?",options:["After 30 days delinquent","After 60 days delinquent","After 90 days delinquent","After 120+ days delinquent"],correctIndex:3,explanation:'Dodd-Frank prohibits starting foreclosure until borrower is 120+ days delinquent. Must contact borrower by day 36, offer loss mitigation, review complete application 37+ days before sale. "Dual tracking" (foreclosure + loss mitigation) prohibited.'},{id:"q303",category:"Financing - Dodd-Frank",question:"Within how many days must lenders respond to borrower complaints under Dodd-Frank?",options:["5 days","15 days","30-45 days","90 days"],correctIndex:2,explanation:"Dodd-Frank requires: Acknowledge complaint in 5 business days, respond within 30 days (45 days max). Response must explain resolution or why no action taken. Must share information about complaint status."},{id:"q304",category:"Financing - Federal Reserve",question:"How many Federal Reserve Districts are there?",options:["7","12","50","100"],correctIndex:1,explanation:"The Federal Reserve System divides the country into 12 districts, each served by a Federal Reserve Bank. Massachusetts is in the First District, served by Federal Reserve Bank of Boston."},{id:"q305",category:"Financing - Federal Reserve",question:"What are the Fed's three main tools to control money supply?",options:["Taxes, spending, borrowing","Reserve requirements, discount rates, open market operations","Mortgages, bonds, stocks","Inflation, employment, GDP"],correctIndex:1,explanation:"The Fed uses: 1) Reserve Requirements (how much banks must hold in reserve), 2) Discount Rates (interest rate Fed charges banks), 3) Open Market Operations (buying/selling Treasury securities). These control money supply and interest rates."},{id:"q306",category:"Financing - Federal Reserve",question:"If the Fed INCREASES reserve requirements, what happens?",options:["More money available for loans, rates decrease","Less money available for loans, rates increase","No effect on interest rates","Only affects savings accounts"],correctIndex:1,explanation:"Increase reserve requirements: Banks must hold more in reserve → Less money to lend → Interest rates increase → Economy slows down. Opposite: Decrease reserve → More lending → Rates decrease → Economy stimulated."},{id:"q307",category:"Financing - Federal Reserve",question:"When Fed rates are HIGH, what typically happens to the housing market?",options:["More people buy homes","Mortgage rates decrease","Fewer people can afford to buy, market slows down","No effect on housing"],correctIndex:2,explanation:"High Fed rates → High mortgage rates → Fewer buyers can afford homes → Housing market slows → Cools inflation. Low Fed rates → Low mortgage rates → More buyers → Hot housing market → Stimulates economy."},{id:"q308",category:"Financing - Federal Reserve",question:"If the Fed BUYS Treasury securities (open market operations), what happens?",options:["Money supply decreases","Money supply increases, economy expands","No effect on money supply","Only affects government"],correctIndex:1,explanation:"Fed buys securities: Money supply increases (money flows from govt to investors) → More money for lending → Interest rates decrease → Economy expands. Fed sells securities: Opposite effect (money supply decreases, rates increase)."},{id:"q309",category:"Financing - Federal Reserve",question:'What is the Fed\'s "dual mandate"?',options:["Control banks and regulate mortgages","Maximum employment and price stability (2% inflation)","Print money and collect taxes","Set mortgage rates and approve loans"],correctIndex:1,explanation:"The Fed's dual mandate: 1) Maximum Employment (keep unemployment low), 2) Price Stability (keep inflation around 2% target). Fed balances these by raising rates (fight inflation) or lowering rates (stimulate employment)."},{id:"q310",category:"Financing - Federal Reserve",question:"Does the Fed directly set mortgage rates?",options:["Yes, the Fed sets all mortgage rates","No - Fed influences rates but doesn't directly set them","Only for FHA/VA loans","Only for jumbo loans"],correctIndex:1,explanation:"NO! The Fed sets Federal Funds Rate (overnight bank lending) and Discount Rate. Mortgage rates are influenced by these but also by: 10-year Treasury yields (biggest factor), mortgage-backed securities market, inflation expectations, credit markets, lender competition."},{id:"q311",category:"Financing - Foreclosure",question:'What is "Deed in Lieu of Foreclosure"?',options:["Foreclosure by court order","Borrower voluntarily gives deed to lender to avoid foreclosure","Lender sells property at auction","Borrower refinances to stop foreclosure"],correctIndex:1,explanation:'Deed in Lieu: Borrower voluntarily gives deed to lender ("Jingle Mail") to avoid foreclosure expense. Faster (30-90 days), less credit damage. MAJOR ISSUE: All junior liens remain (unlike foreclosure which wipes them out). Lender loses FHA/PMI/VA guarantees.'},{id:"q312",category:"Financing - Foreclosure",question:"What happens to junior liens when a 1st mortgage forecloses?",options:["All liens remain on property","Junior liens (recorded AFTER 1st mortgage) are wiped out","Only tax liens are wiped out","Buyer must pay all liens"],correctIndex:1,explanation:"Foreclosure wipes out all junior liens recorded AFTER the foreclosing mortgage. Senior liens (recorded BEFORE) remain. Property taxes ALWAYS survive (priority). Buyer receives deed with no warranties, subject to unpaid taxes and labor liens."},{id:"q313",category:"Financing - Deficiency",question:"If foreclosure sale price is $250K but debt was $300K + $10K costs, what is deficiency?",options:["$0 - no deficiency","$50,000","$60,000","$310,000"],correctIndex:2,explanation:"Deficiency = (Debt + Costs) - Sale Price. ($300K + $10K) - $250K = $60,000. Borrower is liable for $60K. Bank may sue or forgive (treated as taxable income, 1099-C form). Excess proceeds (rare) returned to borrower."},{id:"q314",category:"Financing - Recording",question:'What is "Constructive Notice" in real estate recording?',options:["Lender must notify borrower of all changes","Legal presumption everyone knows about recorded documents","Notice that construction is complete","Written notice to neighbors"],correctIndex:1,explanation:"Constructive Notice: Legal presumption that everyone has knowledge of recorded documents, whether they actually looked or not. Recording at Registry of Deeds provides constructive notice. Establishes lien priority. Buyers assumed to know about recorded liens."},{id:"q315",category:"Financing - Recording MA",question:"What are the two recording systems in Massachusetts?",options:["Public and private","Registry System and Torrens System","Federal and state","Temporary and permanent"],correctIndex:1,explanation:"MA has two systems: 1) Registry System (most common) - documents recorded chronologically, must search all prior documents, first to record has priority. 2) Torrens System (rare) - certificate of title system, state guarantees title, mostly older Boston/Cambridge properties."}];export{e as quizQuestions};
